function registerSlot<P>(ctx: Context, name: string, component: ComponentType<P>, order: number): void {
  const host = ctx as unknown as Record<string, unknown> & SlotHost;
  const holders: unknown[] = [
    host.slot,
    host.slots,
    (host.router as Record<string, unknown> | undefined)?.slot,
    (host.router as Record<string, unknown> | undefined)?.slots,
    (host.ui as Record<string, unknown> | undefined)?.slot,
    (host.ui as Record<string, unknown> | undefined)?.slots,
    (host.client as Record<string, unknown> | undefined)?.slot,
    (host.client as Record<string, unknown> | undefined)?.slots,
  ];

  for (const holder of holders) {
    if (!holder) continue;
    const registrars: unknown[] = [];
    if (typeof holder === "function") registrars.push(holder);
    else if (typeof holder === "object") {
      const api = holder as { register?: unknown; add?: unknown };
      if (typeof api.register === "function") registrars.push(api.register);
      if (typeof api.add === "function") registrars.push(api.add);
