type TodoTag = { id: string; name: string; color: string; createdAt: string };
type TaskRef = { id: string; title?: string; state?: string };

const BASE = "/api/app/todo-tags";

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> { ... }

const state = {
  tags: [] as TodoTag[],
  assignments: {} as Record<string, TodoTag[]>,
  loaded: false,
  error: "",
};
const listeners = new Set<() => void>();
function emit() { for (const l of [...listeners]) l(); }
function subscribe(l: () => void) { listeners.add(l); return () => listeners.delete(l); }

let inflight: Promise<void> | null = null;
async function ensureLoaded(force = false) {
  if (state.loaded && !force) return;
  if (inflight) return inflight;
  inflight = (async () => {
    try {
      const [tagsRes, assignRes] = await Promise.all([
        requestJson<{ tags: TodoTag[] }>(`${BASE}/tags`),
        requestJson<{ assignments: Record<string, TodoTag[]> }>(`${BASE}/assignments`),
      ]);
      state.tags = tagsRes.tags ?? [];
      state.assignments = assignRes.assignments ?? {};
      state.error = "";
      state.loaded = true;
    } catch (err) {
      state.error = message(err);
    } finally {
      inflight = null;
      emit();
    }
  })();
  return inflight;
}
```

