type SlotRegistryApi = {
  register?: (registration: unknown, component?: unknown, options?: unknown) => unknown;
  add?: (registration: unknown, component?: unknown, options?: unknown) => unknown;
};

type SlotHost = {
  slot?: SlotRegistryApi;
  slots?: SlotRegistryApi;
  router?: { slot?: SlotRegistryApi; slots?: SlotRegistryApi };
  ui?: { slot?: SlotRegistryApi; slots?: SlotRegistryApi };
  client?: { slot?: SlotRegistryApi; slots?: SlotRegistryApi };
};

function registerSlot<P>(
  ctx: Context,
  name: string,
  component: ComponentType<P>,
  order: number,
): void {
  const host = ctx as unknown as SlotHost;
  const candidates: SlotRegistryApi[] = [];
  for (const api of [host.slot, host.slots, host.ui?.slot, host.ui?.slots, host.router?.slot, host.router?.slots, host.client?.slot, host.client?.slots]) {
    if (api && typeof api === "object") candidates.push(api);
  }
  for (const api of candidates) {
    const register = typeof api.register === "function" ? api.register : typeof api.add === "function" ? api.add : undefined;
    if (!register) continue;
    const attempts: Array<() => unknown> = register.length >= 2
      ? [
          () => register.call(api, name, component, { order }),
          () => register.call(api, { name, order, component }),
        ]
      : [
          () => register.call(api, { name, order, component }),
          () => register.call(api, name, component, { order }),
        ];
    for (const attempt of attempts) {
      try {
        attempt();
        return;
      } catch {
        // try the next registration shape
      }
    }
  }
}

