  useEffect(() => {
    const unsub = subscribe(() => setVersion((v) => v + 1));
    void ensureLoaded();
    return unsub;
  }, []);
  return { tags: state.tags, assignments: state.assignments, error: state.error, refresh: () => ensureLoaded(true) };
}
