setTaskTags(taskId: string, tagIds: readonly string[]): TodoTag[] {
  const unique = Array.from(new Set(tagIds.map((id) => id.trim()).filter((id) => id.length > 0)));
  const known = new Set(this.list().map((tag) => tag.id));
  const unknown = unique.filter((id) => !known.has(id));
  if (unknown.length > 0) throw httpError(400, `Unknown tag id: ${unknown[0]}`);
  this.db.prepare("DELETE FROM plg_todo_tags__task_tags WHERE task_id = ?").run(taskId);
  const now = new Date().toISOString();
  for (const tagId of unique) {
    this.db.prepare("INSERT INTO plg_todo_tags__task_tags (task_id, tag_id, created_at) VALUES (?, ?, ?)").run(taskId, tagId, now);
  }
  this.ctx.emit("todo-tags:changed", { kind: "assignment-changed", taskId, tagIds: unique });
  return this.listForTask(taskId);
}
```

