function applyAssignments(taskId: string, tags: readonly TodoTag[]): void {
  tagState.assignments = { ...tagState.assignments, [taskId]: Array.from(tags) };
  notify();
}

async function setTaskTags(taskId: string, tagIds: readonly string[]): Promise<void> {
  const result = await requestJson<{ tags: TodoTag[] }>(
    `${TAG_API}/tasks/${encodeURIComponent(taskId)}/tags`,
    { method: "PUT", body: JSON.stringify({ tagIds }) },
  );
  applyAssignments(taskId, result.tags ?? []);
