function TagEditorDialog({
  taskId,
  taskTitle,
  initialTagIds,
  onClose,
}: {
  readonly taskId: string;
  readonly taskTitle: string;
  readonly initialTagIds: readonly string[];
  readonly onClose: () => void;
}) {
  const state = useTagState();
  const [selected, setSelected] = useState<string[]>(() => Array.from(initialTagIds));
  const [draft, setDraft] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const toggle = (tagId: string) => {
    setSelected((current) =>
      current.includes(tagId)
        ? current.filter((id) => id !== tagId)
        : [...current, tagId],
    );
  };

  const handleCreate = async (event: FormEvent) => {
    event.preventDefault();
    const name = draft.trim();
    if (!name || busy) return;
    setBusy(true);
    setError("");
    try {
      const tag = await createTag(name);
      setSelected((current) => (current.includes(tag.id) ? current : [...current, tag.id]));
      setDraft("");
    } catch (createError) {
      setError(describe(createError));
    } finally {
      setBusy(false);
    }
  };

  const handleSave = async () => {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      await setTaskTags(taskId, selected);
      onClose();
    } catch (saveError) {
      setError(describe(saveError));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center bg-black/35 p-3 md:items-center"
      onClick={onClose}
      role="presentation"
    >
      <div
        role="dialog"
        aria-modal="true"
        aria-label={`编辑标签：${taskTitle}`}
        data-tag-editor={taskId}
        onClick={(event) => event.stopPropagation()}
        className="flex w-full max-w-sm flex-col gap-3 rounded-xl border border-line bg-surface p-4 shadow-2xl"
      >
        ... header
        ... tag toggle list (max-h-56 overflow-y-auto)
        ... create form
        ... error
        ... footer buttons
      </div>
    </div>
  );
}
