list(): TodoTag[] {
  const rows = this.db.prepare("SELECT id, name, color, created_at FROM plg_todo_tags__tags ORDER BY name COLLATE NOCASE ASC, created_at ASC").all<TagRow>();
  return rows.map(toTag);
}

get(id: string): TodoTag | null {
  const row = this.db.prepare("SELECT id, name, color, created_at FROM plg_todo_tags__tags WHERE id = ?").get<TagRow>(id);
  return row ? toTag(row) : null;
}

create(input: string | CreateTodoTagInput): TodoTag {
  const rawName = typeof input === "string" ? input : input.name;
  const name = typeof rawName === "string" ? rawName.trim() : "";
  if (!name) throw httpError(400, "Tag name is required");
  if (name.length > MAX_TAG_NAME_LENGTH) throw httpError(400, `Tag name must be at most ${MAX_TAG_NAME_LENGTH} characters`);
  const duplicate = this.db.prepare("SELECT id FROM plg_todo_tags__tags WHERE name = ? COLLATE NOCASE").get<{ id: string }>(name);
  if (duplicate) throw httpError(409, `Tag already exists: ${name}`);
  const color = normalizeColor(typeof input === "string" ? undefined : input.color);
  const id = globalThis.crypto.randomUUID();
  const now = new Date().toISOString();
  this.db.prepare("INSERT INTO plg_todo_tags__tags (id, name, color, created_at) VALUES (?, ?, ?, ?)").run(id, name, color, now);
  const created = this.get(id)!;
  this.ctx.emit("todo-tags:changed", { taskId: "", tagIds: [] });
  return created;
}
