type SlotApi = {
  register?: (registration: unknown, component?: unknown, options?: unknown) => unknown;
  add?: (registration: unknown, component?: unknown, options?: unknown) => unknown;
};

function registerSlot(ctx: Context, name: string, component: ComponentType<ItemSlotProps>, order: number): boolean {
  const holder = ctx as unknown as Record<string, unknown> & {
    router?: { slot?: SlotApi; slots?: SlotApi };
    ui?: { slot?: SlotApi; slots?: SlotApi };
    client?: { slot?: SlotApi; slots?: SlotApi };
    slot?: SlotApi;
    slots?: SlotApi;
  };
  const candidates: SlotApi[] = [];
  for (const api of [holder.slot, holder.slots, holder.ui?.slot, holder.ui?.slots, holder.client?.slot, holder.client?.slots, holder.router?.slot, holder.router?.slots]) {
    if (api && typeof api === "object") candidates.push(api);
  }
  for (const api of candidates) {
    const register = api.register ?? api.add;
    if (typeof register !== "function") continue;
    try {
      register.call(api, { name, order, component });
      return true;
    } catch { /* try next signature */ }
    try {
      register.call(api, name, component, { order });
      return true;
    } catch { /* try next api */ }
  }
  return false;
}
