import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface TagShape {
  readonly id: string;
  readonly name: string;
  readonly color: string;
}

interface TagListBody {
  readonly tags: readonly TagShape[];
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = globalThis.crypto.randomUUID().slice(0, 8);
  const tagName = `紧急-${suffix}`;
  const secondaryName = `前端-${suffix}`;

  const taskResponse = await ctx.request({
    method: "POST",
    path: "/api/app/todo-core/tasks",
    body: { title: `Contract Tags Task ${suffix}` },
  });
  assert.equal(taskResponse.status, 201);
  const taskId = (taskResponse.body as { task: { id: string } }).task.id;

  const initialTags = await ctx.request({
    method: "GET",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
  });
  assert.equal(initialTags.status, 200);
  assert.deepEqual((initialTags.body as TagListBody).tags, []);

  const createdTag = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: tagName, color: "#ef4444" },
  });
  assert.equal(createdTag.status, 201);
  const tag = (createdTag.body as { tag: TagShape }).tag;
  assert.equal(tag.name, tagName);
  assert.equal(tag.color, "#ef4444");

  const duplicate = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: `  ${tagName.toUpperCase()}  ` },
  });
  assert.equal(duplicate.status, 409);

  const invalidName = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: "   " },
  });
  assert.equal(invalidName.status, 400);

  const catalog = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/tags",
  });
  assert.equal(catalog.status, 200);
  assert.ok(
    (catalog.body as TagListBody).tags.some((item) => item.id === tag.id),
  );

  const assigned = await ctx.request({
    method: "PUT",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagIds: [tag.id] },
  });
  assert.equal(assigned.status, 200);
  assert.deepEqual(
    (assigned.body as TagListBody).tags.map((item) => item.id),
    [tag.id],
  );

  const taskTags = await ctx.request({
    method: "GET",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
  });
  assert.equal(taskTags.status, 200);
  assert.deepEqual(
    (taskTags.body as TagListBody).tags.map((item) => item.id),
    [tag.id],
  );

  const assignments = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/assignments",
  });
  assert.equal(assignments.status, 200);
  const assignmentMap = (
    assignments.body as { assignments: Record<string, readonly TagShape[]> }
  ).assignments;
  assert.deepEqual(
    (assignmentMap[taskId] ?? []).map((item) => item.id),
    [tag.id],
  );

  const secondary = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: secondaryName },
  });
  assert.equal(secondary.status, 201);
  const secondaryId = (secondary.body as { tag: TagShape }).tag.id;

  const attached = await ctx.request({
    method: "POST",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagId: secondaryId },
  });
  assert.equal(attached.status, 201);
  assert.equal((attached.body as TagListBody).tags.length, 2);

  const detached = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tasks/${taskId}/tags/${secondaryId}`,
  });
  assert.equal(detached.status, 200);
  assert.deepEqual(
    (detached.body as TagListBody).tags.map((item) => item.id),
    [tag.id],
  );

  const unknownTag = await ctx.request({
    method: "PUT",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagIds: ["tag-does-not-exist"] },
  });
  assert.equal(unknownTag.status, 400);

  const unknownTask = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/tasks/task-does-not-exist/tags",
  });
  assert.equal(unknownTask.status, 404);

  const deletedTag = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tags/${tag.id}`,
  });
  assert.equal(deletedTag.status, 200);

  const afterDelete = await ctx.request({
    method: "GET",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
  });
  assert.equal(afterDelete.status, 200);
  assert.deepEqual((afterDelete.body as TagListBody).tags, []);

  const deletedAgain = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tags/${tag.id}`,
  });
  assert.equal(deletedAgain.status, 404);
}

