        ) : (
          tags.map((tag) => (
            <TagChip
              key={tag.id}
              tag={tag}
              onRemove={() =>
                void run(async () => {
                  await detachTag(task.id, tag.id);
                })
              }
            />
          ))
        )}
      </div>

      {available.length > 0 && (
        <div className="flex flex-wrap items-center gap-1.5">
          {available.map((tag) => (
            <button
              key={tag.id}
              type="button"
              data-tag-add={tag.id}
              disabled={busy}
              onClick={() =>
                void run(async () => {
                  await attachTag(task.id, tag.id);
