import type { TodoCounterService, TodoCounterStats } from "./contract.d.ts";

interface TodoLookup {
  list(filter?: { readonly state?: "open" | "done" }): ReadonlyArray<{ readonly state: string }>;
}

function emptyStats(): TodoCounterStats { return { open: 0, done: 0, total: 0 }; }

export default class TodoCounter extends Service implements TodoCounterService {
  constructor(ctx: Context) {
    super(ctx, "todoCounter");
    ctx.http.route("GET", "/stats", () => ({ stats: this.stats() }));
  }

  stats(): TodoCounterStats {
    const todo = this.resolveTodo();
    if (!todo) return emptyStats();
    try {
      const tasks = todo.list();
      let open = 0; let done = 0;
      for (const task of tasks) {
        if (task?.state === "done") done += 1; else open += 1;
      }
      return { open, done, total: open + done };
    } catch { return emptyStats(); }
  }

  private resolveTodo(): TodoLookup | null { ...mirror todo-tags... }
}
