import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface Stats { open: number; done: number; total: number; }

interface BrowserPage {
  waitForSelector(selector: string, options?: { timeout?: number }): Promise<unknown>;
  textContent(selector: string): Promise<string | null>;
  click(selector: string): Promise<unknown>;
}

interface BrowserHandle { page: BrowserPage; pageErrors?: readonly unknown[]; close?: () => Promise<unknown>; }

async function sleep(ms: number) { return new Promise((r) => setTimeout(r, ms)); }

async function waitForCounters(page: BrowserPage, expected: {open:number; done:number}): Promise<{open:number; done:number}> {
  let seen = { open: -1, done: -1 };
  const deadline = Date.now() + 10000;
  while (Date.now() < deadline) {
    const openText = await page.textContent('[data-todo-counter-open="true"]');
    const doneText = await page.textContent('[data-todo-counter-done="true"]');
    const open = Number((openText ?? "").trim());
    const done = Number((doneText ?? "").trim());
    seen = { open, done };
    if (open === expected.open && done === expected.done) return seen;
    await sleep(100);
  }
  throw new Error(`counter did not settle: expected ${JSON.stringify(expected)}, received ${JSON.stringify(seen)}`);
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = globalThis.crypto.randomUUID().slice(0, 8);

  const baselineResponse = await ctx.request({ method: "GET", path: "/api/app/todo-counter/stats" });
  assert.equal(baselineResponse.status, 200);
  const baseline = (baselineResponse.body as { stats: Stats }).stats;

  const first = await ctx.request({ method: "POST", path: "/api/app/todo-core/tasks", body: { title: `Counter UI A ${suffix}` } });
  assert.equal(first.status, 201);
  const firstId = ...;
  const second = ...;
  const secondId = ...;

  const completed = await ctx.request({ method: "POST", path: `/api/app/todo-core/tasks/${secondId}/transition`, body: { nextState: "done" } });
  assert.equal(completed.status, 200);

  const expected = { open: baseline.open + 1, done: baseline.done + 1 };

  const openPage = ctx.openBrowserPage as unknown as (target?: string) => Promise<BrowserHandle>;
  const handle = await openPage("/");
  const page = handle.page;
  try {
    await page.waitForSelector('[data-todo-counter="true"]');
    await page.waitForSelector(`[data-todo-item="${firstId}"]`);
    await waitForCounters(page, expected);

    await page.click(`[data-todo-toggle="${firstId}"]`);
    await waitForCounters(page, { open: baseline.open, done: baseline.done + 2 });

    const pageErrors = handle.pageErrors ?? [];
    assert.equal(pageErrors.length, 0, ...);
  } finally {
    if (typeof handle.close === "function") await handle.close();
  }
}
