import { useEffect, useState, type ComponentType } from "react";
import type { Context } from "cordis";
import { CheckCheck, ListTodo } from "lucide-react";

interface CounterTask {
  readonly id: string;
  readonly state?: string;
}

interface CounterSlotProps {
  readonly tasks?: readonly CounterTask[];
}

interface CounterStats {
  readonly open: number;
  readonly done: number;
  readonly total: number;
}

const ZERO_STATS: CounterStats = { open: 0, done: 0, total: 0 };

function countTasks(tasks: readonly CounterTask[]): CounterStats {
  let open = 0;
  let done = 0;
  for (const task of tasks) {
    if (task.state === "done") done += 1;
    else open += 1;
  }
  return { open, done, total: open + done };
}

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function TodoCounterStatus({ tasks }: CounterSlotProps) {
  const [remoteStats, setRemoteStats] = useState<CounterStats | null>(null);
  const [error, setError] = useState("");

  const derivesFromSlot = Array.isArray(tasks);

  useEffect(() => {
    if (derivesFromSlot) return;
    let cancelled = false;

    void (async () => {
      try {
        const response = await fetch("/api/app/todo-counter/stats");
        if (!response.ok) {
          throw new Error(`请求失败 (${response.status})`);
        }
        const data = (await response.json()) as { stats?: CounterStats };
        if (!cancelled) {
          setRemoteStats(data.stats ?? ZERO_STATS);
          setError("");
        }
      } catch (fetchError) {
        if (!cancelled) {
          setError(describe(fetchError));
        }
      }
    })();

    return () => {
      cancelled = true;
    };
  }, [derivesFromSlot]);

  const stats = derivesFromSlot
    ? countTasks(tasks ?? [])
    : (remoteStats ?? ZERO_STATS);

  return (
    <div
      data-todo-counter="true"
      aria-label="任务计数"
      title={error || undefined}
      className="inline-flex items-center gap-2 rounded-full border border-line bg-surface px-3 py-1 text-xs"
    >
      <span
        data-todo-counter-item="open"
        className="inline-flex items-center gap-1.5"
      >
        <ListTodo className="size-3.5 text-accent" aria-hidden="true" />
        <span className="text-muted">未完成</span>
        <span
          data-todo-counter-open="true"
          className="font-semibold tabular-nums text-ink"
        >
          {stats.open}
        </span>
      </span>
      <span className="h-3.5 w-px bg-line" aria-hidden="true" />
      <span
        data-todo-counter-item="done"
        className="inline-flex items-center gap-1.5"
      >
        <CheckCheck className="size-3.5 text-accent" aria-hidden="true" />
        <span className="text-muted">已完成</span>
        <span
          data-todo-counter-done="true"
          className="font-semibold tabular-nums text-ink"
        >
          {stats.done}
        </span>
      </span>
    </div>
  );
}

type AnyFunction = (arg: unknown, second?: unknown, third?: unknown) => unknown;

function pick(source: unknown, key: string): unknown {
  try {
    if (!source || typeof source !== "object") return undefined;
    return (source as Record<string, unknown>)[key];
  } catch {
    return undefined;
  }
}

function registerSlot<P>(
  ctx: Context,
  name: string,
  component: ComponentType<P>,
  order: number,
): void {
  const holders: unknown[] = [
    pick(ctx, "slot"),
    pick(ctx, "slots"),
    pick(pick(ctx, "router"), "slot"),
    pick(pick(ctx, "router"), "slots"),
    pick(pick(ctx, "ui"), "slot"),
    pick(pick(ctx, "ui"), "slots"),
    pick(pick(ctx, "client"), "slot"),
    pick(pick(ctx, "client"), "slots"),
  ];

  for (const holder of holders) {
    if (!holder) continue;

    const registrars: unknown[] = [];
    if (typeof holder === "function") {
      registrars.push(holder);
    } else if (typeof holder === "object") {
      const api = holder as { register?: unknown; add?: unknown };
      if (typeof api.register === "function") registrars.push(api.register);
      if (typeof api.add === "function") registrars.push(api.add);
    }

    for (const registrar of registrars) {
      const register = registrar as AnyFunction;
      const objectForm = () => register.call(holder, { name, order, component });
      const argsForm = () => register.call(holder, name, component, { order });
      const attempts =
        register.length >= 2 ? [argsForm, objectForm] : [objectForm, argsForm];

      for (const attempt of attempts) {
        try {
          attempt();
          return;
        } catch {
          // try the next registration shape
        }
      }
    }
  }
}

export default function apply(ctx: Context): void {
  registerSlot(ctx, "todo.header.actions", TodoCounterStatus, 10);
}
