import type { PluginTestContext } from "@host/server-sdk";

interface Stats { open: number; done: number; total: number; }

interface BrowserPage {
  waitForSelector(selector: string, options?: { timeout?: number }): Promise<unknown>;
  textContent(selector: string): Promise<string | null>;
  click(selector: string): Promise<unknown>;
}

interface BrowserHandle { page: BrowserPage; pageErrors?: readonly unknown[]; close?: () => Promise<unknown>; }

async function sleep(ms: number) { return new Promise((r) => setTimeout(r, ms)); }

async function waitForCounters(page: BrowserPage, expected: {open:number; done:number}): Promise<{open:number; done:number}> {
  let seen = { open: -1, done: -1 };
  const deadline = Date.now() + 10000;
  while (Date.now() < deadline) {
    const openText = await page.textContent('[data-todo-counter-open="true"]');
    const doneText = await page.textContent('[data-todo-counter-done="true"]');
    const open = Number((openText ?? "").trim());
    const done = Number((doneText ?? "").trim());
    seen = { open, done };
    if (open === expected.open && done === expected.done) return seen;
    await sleep(100);
  }
  throw new Error(`counter did not settle: expected ${JSON.stringify(expected)}, received ${JSON.stringify(seen)}`);
}

