import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface BrowserPage {
  readonly waitForSelector: (
    selector: string,
    options?: { readonly timeout?: number },
  ) => Promise<unknown>;
  readonly textContent: (selector: string) => Promise<string | null>;
  readonly getAttribute: (selector: string, name: string) => Promise<string | null>;
  readonly click: (selector: string) => Promise<unknown>;
}

interface BrowserHandle {
  readonly page: BrowserPage;
  readonly pageErrors?: readonly unknown[];
  readonly close?: () => Promise<unknown>;
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = globalThis.crypto.randomUUID().slice(0, 8);
  const tagName = `ui-${suffix}`;

  const taskResponse = await ctx.request({
    method: "POST",
    path: "/api/app/todo-core/tasks",
    body: { title: `UI Tags Task ${suffix}` },
  });
  assert.equal(taskResponse.status, 201);
  const taskId = (taskResponse.body as { task: { id: string } }).task.id;

  const tagResponse = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: tagName },
  });
  assert.equal(tagResponse.status, 201);
  const tagId = (tagResponse.body as { tag: { id: string } }).tag.id;

  const assigned = await ctx.request({
    method: "PUT",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagIds: [tagId] },
  });
  assert.equal(assigned.status, 200);

  const openPage = ctx.openBrowserPage as unknown as (
    target?: string,
  ) => Promise<BrowserHandle>;
  const handle = await openPage("/");
  const page = handle.page;

  try {
    await page.waitForSelector(`[data-todo-item="${taskId}"]`);
    await page.waitForSelector(`[data-tag-chip="${tagId}"]`);
    const chip = await page.textContent(`[data-tag-chip="${tagId}"]`);
    assert.ok(
      typeof chip === "string" && chip.includes(tagName),
      `expected task-row tag chip "${tagName}", received "${String(chip)}"`,
    );

    await page.click(`[data-tag-edit="${taskId}"]`);
    await page.waitForSelector(`[data-tag-editor="${taskId}"]`);
    const selected = await page.getAttribute(
      `[data-tag-toggle="${tagId}"]`,
      "data-tag-selected",
    );
    assert.equal(selected, "true");
    await page.click(`[data-tag-editor-cancel="true"]`);

    const pageErrors = handle.pageErrors ?? [];
    assert.equal(
      pageErrors.length,
      0,
      `client errors: ${pageErrors.map((item) => String(item)).join(" | ")}`,
    );
  } finally {
    if (typeof handle.close === "function") {
      await handle.close();
    }
  }
}

