import { Service, type Context } from "cordis";
import type { ScopedDb } from "@host/server-sdk";
import type {
  CreateTodoTagInput,
  TodoTag,
  TodoTagsService,
} from "./contract.d.ts";

const DEFAULT_TAG_COLOR = "#64748b";
const MAX_TAG_NAME_LENGTH = 40;

interface TagRow {
  readonly id: string;
  readonly name: string;
  readonly color: string;
  readonly created_at: string;
}

interface TaskTagRow {
  readonly task_id: string;
  readonly tag_id: string;
}

interface TodoLookup {
  get(id: string): { readonly id: string } | null;
}

interface HttpResponse {
  readonly status: number;
  readonly body: Record<string, unknown>;
}

function toTag(row: TagRow): TodoTag {
  return {
    id: row.id,
    name: row.name,
    color: row.color,
    createdAt: row.created_at,
  };
}

function httpError(status: number, message: string): Error & { status: number } {
  const error = new Error(message) as Error & { status: number };
  error.status = status;
  return error;
}

function normalizeColor(value: unknown): string {
  if (typeof value !== "string") return DEFAULT_TAG_COLOR;
  const color = value.trim().toLowerCase();
  return /^#[0-9a-f]{6}$/.test(color) ? color : DEFAULT_TAG_COLOR;
}

function normalizeName(value: unknown): string {
  const name = typeof value === "string" ? value.trim() : "";
  if (!name) {
    throw httpError(400, "Tag name is required");
  }
  if (name.length > MAX_TAG_NAME_LENGTH) {
    throw httpError(
      400,
      `Tag name must be at most ${MAX_TAG_NAME_LENGTH} characters`,
    );
  }
  return name;
}

function toErrorResponse(error: unknown): HttpResponse {
  const status = (error as { status?: unknown } | null)?.status;
  const message = error instanceof Error ? error.message : String(error);
  return {
    status:
      typeof status === "number" && status >= 400 && status < 600
        ? status
        : 500,
    body: { error: message.length > 0 ? message : "Unexpected error" },
  };
}

export default class TodoTagsPlugin
  extends Service
  implements TodoTagsService
{
  private readonly db: ScopedDb;

  constructor(ctx: Context) {
    super(ctx, "todoTags");
    this.db = ctx.db;

    this.db.exec(`
      CREATE TABLE IF NOT EXISTS plg_todo_tags__tags (
        id TEXT PRIMARY KEY,
        name TEXT NOT NULL,
        color TEXT NOT NULL DEFAULT '#64748b',
        created_at TEXT NOT NULL
      )
    `);

    this.db.exec(`
      CREATE TABLE IF NOT EXISTS plg_todo_tags__task_tags (
        task_id TEXT NOT NULL,
        tag_id TEXT NOT NULL,
        created_at TEXT NOT NULL,
        PRIMARY KEY (task_id, tag_id)
      )
    `);

    this.db.exec(`
      CREATE INDEX IF NOT EXISTS idx_plg_todo_tags__task_tags_tag
        ON plg_todo_tags__task_tags (tag_id)
    `);

    ctx.http.route("GET", "/tags", () => ({ tags: this.list() }));

    ctx.http.route("GET", "/tags/:id", (req) => {
      const tag = this.get(req.params.id);
      if (!tag) {
        return { status: 404, body: { error: "Tag not found" } };
      }
      return { tag };
    });

    ctx.http.route("POST", "/tags", (req) => {
      const body = (req.body ?? {}) as { name?: unknown; color?: unknown };
      try {
        const tag = this.create({
          name: typeof body.name === "string" ? body.name : "",
          color: typeof body.color === "string" ? body.color : undefined,
        });
        return { status: 201, body: { tag } };
      } catch (error) {
        return toErrorResponse(error);
      }
    });

    ctx.http.route("DELETE", "/tags/:id", (req) => {
      const deleted = this.delete(req.params.id);
      if (!deleted) {
        return { status: 404, body: { error: "Tag not found" } };
      }
      return { deleted: true, id: req.params.id };
    });

    ctx.http.route("GET", "/assignments", () => ({
      assignments: this.listAssignments(),
    }));

    ctx.http.route("GET", "/tasks/:taskId/tags", (req) => {
      const taskId = req.params.taskId;
      if (this.taskExists(taskId) === false) {
        return { status: 404, body: { error: "Task not found" } };
      }
      return { tags: this.listForTask(taskId) };
    });

    ctx.http.route("POST", "/tasks/:taskId/tags", (req) => {
      const taskId = req.params.taskId;
      const body = (req.body ?? {}) as { tagId?: unknown };
      if (typeof body.tagId !== "string" || body.tagId.trim().length === 0) {
        return { status: 400, body: { error: "tagId is required" } };
      }
      if (this.taskExists(taskId) === false) {
        return { status: 404, body: { error: "Task not found" } };
      }
      try {
        return {
          status: 201,
          body: { tags: this.attachTag(taskId, body.tagId) },
        };
      } catch (error) {
        return toErrorResponse(error);
      }
    });

    ctx.http.route("PUT", "/tasks/:taskId/tags", (req) => {
      const taskId = req.params.taskId;
      const body = (req.body ?? {}) as { tagIds?: unknown };
      if (
        !Array.isArray(body.tagIds) ||
        body.tagIds.some((value) => typeof value !== "string")
      ) {
        return {
          status: 400,
          body: { error: "tagIds must be an array of tag ids" },
        };
      }
      if (this.taskExists(taskId) === false) {
        return { status: 404, body: { error: "Task not found" } };
      }
      try {
        return { tags: this.setTaskTags(taskId, body.tagIds as string[]) };
      } catch (error) {
        return toErrorResponse(error);
      }
    });

    ctx.http.route("DELETE", "/tasks/:taskId/tags/:tagId", (req) => {
      const taskId = req.params.taskId;
      if (this.taskExists(taskId) === false) {
        return { status: 404, body: { error: "Task not found" } };
      }
      return { tags: this.detachTag(taskId, req.params.tagId) };
    });
  }

  list(): TodoTag[] {
    const rows = this.db
      .prepare(
        "SELECT id, name, color, created_at FROM plg_todo_tags__tags ORDER BY name COLLATE NOCASE ASC, created_at ASC",
      )
      .all<TagRow>();
    return rows.map(toTag);
  }

  get(id: string): TodoTag | null {
    const row = this.db
      .prepare(
        "SELECT id, name, color, created_at FROM plg_todo_tags__tags WHERE id = ?",
      )
      .get<TagRow>(id);
    return row ? toTag(row) : null;
  }

  create(input: string | CreateTodoTagInput): TodoTag {
    const name = normalizeName(
      typeof input === "string" ? input : input.name,
    );
    const duplicate = this.db
      .prepare(
        "SELECT id FROM plg_todo_tags__tags WHERE name = ? COLLATE NOCASE",
      )
      .get<{ id: string }>(name);
    if (duplicate) {
      throw httpError(409, `Tag already exists: ${name}`);
    }

    const color = normalizeColor(
      typeof input === "string" ? undefined : input.color,
    );
    const id = globalThis.crypto.randomUUID();
    const now = new Date().toISOString();

    this.db
      .prepare(
        "INSERT INTO plg_todo_tags__tags (id, name, color, created_at) VALUES (?, ?, ?, ?)",
      )
      .run(id, name, color, now);

    const created = this.get(id)!;
    this.ctx.emit("todo-tags:changed", {
      kind: "tag-created",
      tagId: created.id,
    });
    return created;
  }

  delete(id: string): boolean {
    const existing = this.get(id);
    if (!existing) return false;

    this.db
      .prepare("DELETE FROM plg_todo_tags__task_tags WHERE tag_id = ?")
      .run(id);
    const result = this.db
      .prepare("DELETE FROM plg_todo_tags__tags WHERE id = ?")
      .run(id);

    this.ctx.emit("todo-tags:changed", { kind: "tag-deleted", tagId: id });
    return Number(result.changes) > 0;
  }

  listForTask(taskId: string): TodoTag[] {
    const rows = this.db
      .prepare(
        "SELECT t.id AS id, t.name AS name, t.color AS color, t.created_at AS created_at FROM plg_todo_tags__tags t INNER JOIN plg_todo_tags__task_tags a ON a.tag_id = t.id WHERE a.task_id = ? ORDER BY a.created_at ASC, t.name COLLATE NOCASE ASC",
      )
      .all<TagRow>(taskId);
    return rows.map(toTag);
  }

  listAssignments(): Record<string, TodoTag[]> {
    const rows = this.db
      .prepare(
        "SELECT task_id, tag_id FROM plg_todo_tags__task_tags ORDER BY created_at ASC",
      )
      .all<TaskTagRow>();
    const tags = new Map(this.list().map((tag) => [tag.id, tag]));
    const result: Record<string, TodoTag[]> = {};

    for (const row of rows) {
      const tag = tags.get(row.tag_id);
      if (!tag) continue;
      const list = result[row.task_id];
      if (list) list.push(tag);
      else result[row.task_id] = [tag];
    }

    for (const taskId of Object.keys(result)) {
      if (this.taskExists(taskId) === false) {
        delete result[taskId];
        this.db
          .prepare("DELETE FROM plg_todo_tags__task_tags WHERE task_id = ?")
          .run(taskId);
      }
    }

    return result;
  }

  setTaskTags(taskId: string, tagIds: readonly string[]): TodoTag[] {
    const unique: string[] = [];
    for (const raw of tagIds) {
      const tagId = typeof raw === "string" ? raw.trim() : "";
      if (tagId.length > 0 && !unique.includes(tagId)) unique.push(tagId);
    }

    const known = new Set(this.list().map((tag) => tag.id));
    const unknown = unique.filter((tagId) => !known.has(tagId));
    if (unknown.length > 0) {
      throw httpError(400, `Unknown tag id: ${unknown[0]}`);
    }

    this.db
      .prepare("DELETE FROM plg_todo_tags__task_tags WHERE task_id = ?")
      .run(taskId);
    const now = new Date().toISOString();
    const insert = this.db.prepare(
      "INSERT INTO plg_todo_tags__task_tags (task_id, tag_id, created_at) VALUES (?, ?, ?)",
    );
    for (const tagId of unique) {
      insert.run(taskId, tagId, now);
    }

    this.ctx.emit("todo-tags:changed", {
      kind: "assignment-changed",
      taskId,
      tagIds: unique,
    });
    return this.listForTask(taskId);
  }

  attachTag(taskId: string, tagId: string): TodoTag[] {
    if (!this.get(tagId)) {
      throw httpError(400, `Unknown tag id: ${tagId}`);
    }
    const current = this.listForTask(taskId).map((tag) => tag.id);
    if (!current.includes(tagId)) {
      this.db
        .prepare(
          "INSERT INTO plg_todo_tags__task_tags (task_id, tag_id, created_at) VALUES (?, ?, ?)",
        )
        .run(taskId, tagId, new Date().toISOString());
      this.ctx.emit("todo-tags:changed", {
        kind: "assignment-changed",
        taskId,
        tagIds: [...current, tagId],
      });
    }
    return this.listForTask(taskId);
  }

  detachTag(taskId: string, tagId: string): TodoTag[] {
    const result = this.db
      .prepare(
        "DELETE FROM plg_todo_tags__task_tags WHERE task_id = ? AND tag_id = ?",
      )
      .run(taskId, tagId);
    if (Number(result.changes) > 0) {
      this.ctx.emit("todo-tags:changed", {
        kind: "assignment-changed",
        taskId,
        tagIds: this.listForTask(taskId).map((tag) => tag.id),
      });
    }
    return this.listForTask(taskId);
  }

  private resolveTodo(): TodoLookup | null {
    try {
      const direct = (this.ctx as unknown as { todo?: TodoLookup }).todo;
      if (direct && typeof direct.get === "function") return direct;
    } catch {
      // todo service is not available in this composition
    }

    try {
      const get = (this.ctx as unknown as { get?: (name: string) => unknown })
        .get;
      if (typeof get === "function") {
        const resolved = get.call(this.ctx, "todo") as TodoLookup | undefined;
        if (resolved && typeof resolved.get === "function") return resolved;
      }
    } catch {
      // todo service is not available in this composition
    }

    return null;
  }

  private taskExists(taskId: string): boolean | null {
    const todo = this.resolveTodo();
    if (!todo) return null;
    try {
      const task = todo.get(taskId);
      return task !== null && task !== undefined;
    } catch {
      return null;
    }
  }
}

