  const canonicalSecondaryName = `frontend-${suffix}`;

  // snapshot existing tags to verify historical data stays readable
  const initialCatalog = await ctx.request({ method: "GET", path: "/api/app/todo-tags/tags" });
  assert.equal(initialCatalog.status, 200);
  const initialNames = new Map(
    (initialCatalog.body as TagListBody).tags.map((tag) => [tag.id, tag.name]),
  );

  const taskResponse = ...
  const taskId = ...

  const initialTags = GET /tasks/:id/tags -> []

  // create with mixed case + whitespace
  const createdTag = POST /tags { name: rawTagName, color: "#EF4444" };
  assert.equal(status, 201);
  assert.equal(body.deduplicated, false);
  tag.name === canonicalTagName
  tag.color === "#ef4444"

  // dedupe case variant
  const duplicate = POST { name: canonicalTagName.toUpperCase(), color: "#3b82f6" };
  assert.equal(duplicate.status, 200);
  assert.equal(body.deduplicated, true);
  assert.equal(dupTag.id, tag.id);
  assert.equal(dupTag.name, canonicalTagName);
  assert.equal(dupTag.color, "#ef4444"); // existing color preserved

  // catalog contains exactly one tag with this id
  const catalog = GET /tags
  assert.equal(catalog.tags.filter(t => t.id === tag.id).length, 1);

  // historical snapshot unchanged
