import type {} from "cordis";

export interface TodoTag {
  readonly id: string;
  readonly name: string;
  readonly color: string;
  readonly createdAt: string;
}

export interface CreateTodoTagInput {
  readonly name: string;
  readonly color?: string;
}

/**
 * HTTP response body for `POST /api/app/todo-tags/tags`.
 * A newly inserted tag returns `deduplicated: false` with status 201; a save
 * that matches an existing tag returns status 200 and the stored tag with
 * `deduplicated: true`.
 */
export interface CreateTodoTagResponse {
  readonly tag: TodoTag;
  readonly deduplicated: boolean;
}

export type TodoTagsChangeKind =
  | "tag-created"
  | "tag-deleted"
  | "assignment-changed";

export interface TodoTagsChangedPayload {
  readonly kind: TodoTagsChangeKind;
  readonly tagId?: string;
  readonly taskId?: string;
  readonly tagIds?: readonly string[];
}

export interface TodoTagsService {
  list(): TodoTag[];
  get(id: string): TodoTag | null;
  /**
   * Trims and lowercases the name before saving. When a tag with the same
   * normalized name already exists, that stored tag is returned unchanged so
   * historical names stay readable and no duplicate is inserted.
   */
  create(input: string | CreateTodoTagInput): TodoTag;
  delete(id: string): boolean;
  listForTask(taskId: string): TodoTag[];
  listAssignments(): Record<string, TodoTag[]>;
  setTaskTags(taskId: string, tagIds: readonly string[]): TodoTag[];
  attachTag(taskId: string, tagId: string): TodoTag[];
  detachTag(taskId: string, tagId: string): TodoTag[];
}

export interface TodoTagsItemSlotContext {
  readonly task: {
    readonly id: string;
    readonly title: string;
    readonly state: "open" | "done";
  };
  readonly refresh: () => Promise<void>;
}

