  assert.equal(initialTags.status, 200);
  assert.deepEqual((initialTags.body as TagListBody).tags, []);

  // Mixed-case/whitespace input is stored and returned as lowercase.
  const createdTag = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: rawTagName, color: "#EF4444" },
  });
  assert.equal(createdTag.status, 201);
  const createdBody = createdTag.body as CreateTagBody;
  assert.equal(createdBody.deduplicated, false);
  assert.equal(createdBody.tag.name, canonicalTagName);
  assert.equal(createdBody.tag.color, "#ef4444");
  const tag = createdBody.tag;

  const fetched = await ctx.request({
    method: "GET",
    path: `/api/app/todo-tags/tags/${tag.id}`,
  });
  assert.equal(fetched.status, 200);
  assert.equal((fetched.body as { tag: TagShape }).tag.name, canonicalTagName);

  // Case-variant save dedupes onto the existing tag instead of inserting.
  const duplicate = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: canonicalTagName.toUpperCase(), color: "#3b82f6" },
  });
  assert.equal(duplicate.status, 200);
  const duplicateBody = duplicate.body as CreateTagBody;
  assert.equal(duplicateBody.deduplicated, true);
  assert.equal(duplicateBody.tag.id, tag.id);
  assert.equal(duplicateBody.tag.name, canonicalTagName);
  assert.equal(duplicateBody.tag.color, "#ef4444");

  const catalog = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/tags",
  });
  assert.equal(catalog.status, 200);
  const catalogTags = (catalog.body as TagListBody).tags;
  assert.equal(
    catalogTags.filter((item) => item.id === tag.id).length,
    1,
    "case-variant save must not insert a duplicate tag row",
  );

  for (const [id, name] of historicalNames) {
    const current = catalogTags.find((item) => item.id === id);
    assert.equal(current?.name, name, `historical tag ${id} was rewritten`);
  }

  const invalidName = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: "   " },
  });
  assert.equal(invalidName.status, 400);

  const tooLongName = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: "A".repeat(41) },
  });
  assert.equal(tooLongName.status, 400);

  const assigned = await ctx.request({
    method: "PUT",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagIds: [tag.id, tag.id] },
  });
  assert.equal(assigned.status, 200);
  assert.deepEqual(
    (assigned.body as TagListBody).tags.map((item) => item.id),
    [tag.id],
    "assignment payload should deduplicate repeated tag ids",
  );

  const taskTags = await ctx.request({
    method: "GET",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
  });
  assert.equal(taskTags.status, 200);
  assert.deepEqual(
    (taskTags.body as TagListBody).tags.map((item) => item.id),
    [tag.id],
  );

  const assignments = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/assignments",
  });
  assert.equal(assignments.status, 200);
  const assignmentMap = (
    assignments.body as { assignments: Record<string, readonly TagShape[]> }
  ).assignments;
  assert.deepEqual(
    (assignmentMap[taskId] ?? []).map((item) => item.id),
    [tag.id],
  );

  const secondary = await ctx.request({
    method: "POST",
    path: "/api/app/todo-tags/tags",
    body: { name: rawSecondaryName },
  });
  assert.equal(secondary.status, 201);
  const secondaryBody = secondary.body as CreateTagBody;
  assert.equal(secondaryBody.deduplicated, false);
  assert.equal(secondaryBody.tag.name, canonicalSecondaryName);
  const secondaryId = secondaryBody.tag.id;

  const attached = await ctx.request({
    method: "POST",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagId: secondaryId },
  });
  assert.equal(attached.status, 201);
  assert.equal((attached.body as TagListBody).tags.length, 2);

  const detached = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tasks/${taskId}/tags/${secondaryId}`,
  });
  assert.equal(detached.status, 200);
  assert.deepEqual(
    (detached.body as TagListBody).tags.map((item) => item.id),
    [tag.id],
  );

  const unknownTag = await ctx.request({
    method: "PUT",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
    body: { tagIds: ["tag-does-not-exist"] },
  });
  assert.equal(unknownTag.status, 400);

  const unknownTask = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/tasks/task-does-not-exist/tags",
  });
  assert.equal(unknownTask.status, 404);

  const deletedTag = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tags/${tag.id}`,
  });
  assert.equal(deletedTag.status, 200);

  const afterDelete = await ctx.request({
    method: "GET",
    path: `/api/app/todo-tags/tasks/${taskId}/tags`,
  });
  assert.equal(afterDelete.status, 200);
  assert.deepEqual((afterDelete.body as TagListBody).tags, []);

  const deletedAgain = await ctx.request({
    method: "DELETE",
    path: `/api/app/todo-tags/tags/${tag.id}`,
  });
  assert.equal(deletedAgain.status, 404);

  const finalCatalog = await ctx.request({
    method: "GET",
    path: "/api/app/todo-tags/tags",
  });
  assert.equal(finalCatalog.status, 200);
  const finalTags = (finalCatalog.body as TagListBody).tags;
  for (const [id, name] of historicalNames) {
    const current = finalTags.find((item) => item.id === id);
    assert.equal(current?.name, name, `historical tag ${id} was rewritten`);
  }
}
