import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface CounterStats {
  readonly open: number;
  readonly done: number;
  readonly total: number;
}

interface BrowserPage {
  readonly waitForSelector: (
    selector: string,
    options?: { readonly timeout?: number },
  ) => Promise<unknown>;
  readonly textContent: (selector: string) => Promise<string | null>;
  readonly click: (selector: string) => Promise<unknown>;
}

interface BrowserHandle {
  readonly page: BrowserPage;
  readonly pageErrors?: readonly unknown[];
  readonly close?: () => Promise<unknown>;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function waitForCounters(
  page: BrowserPage,
  expected: { readonly open: number; readonly done: number },
): Promise<void> {
  const deadline = Date.now() + 8000;
  let seen = { open: -1, done: -1 };

  while (Date.now() < deadline) {
    const openText = await page.textContent('[data-todo-counter-open="true"]');
    const doneText = await page.textContent('[data-todo-counter-done="true"]');
    const open = Number((openText ?? "").trim());
    const done = Number((doneText ?? "").trim());
    seen = { open, done };
    if (open === expected.open && done === expected.done) return;
    await sleep(100);
  }

  throw new Error(
    `counter did not settle: expected ${JSON.stringify(expected)}, received ${JSON.stringify(seen)}`,
  );
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = globalThis.crypto.randomUUID().slice(0, 8);

  const baselineResponse = await ctx.request({
    method: "GET",
    path: "/api/app/todo-counter/stats",
  });
  assert.equal(baselineResponse.status, 200);
  const baseline = (baselineResponse.body as { stats: CounterStats }).stats;

  const first = await ctx.request({
    method: "POST",
    path: "/api/app/todo-core/tasks",
    body: { title: `Counter UI A ${suffix}` },
  });
  assert.equal(first.status, 201);
  const firstId = (first.body as { task: { id: string } }).task.id;

  const second = await ctx.request({
    method: "POST",
    path: "/api/app/todo-core/tasks",
    body: { title: `Counter UI B ${suffix}` },
  });
  assert.equal(second.status, 201);
  const secondId = (second.body as { task: { id: string } }).task.id;

  const completed = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${secondId}/transition`,
    body: { nextState: "done" },
  });
  assert.equal(completed.status, 200);

  const openPage = ctx.openBrowserPage as unknown as (
    target?: string,
  ) => Promise<BrowserHandle>;
  const handle = await openPage("/");
  const page = handle.page;

  try {
    await page.waitForSelector('[data-todo-counter="true"]', {
      timeout: 8000,
    });
    await page.waitForSelector(`[data-todo-item="${firstId}"]`, {
      timeout: 8000,
    });

    await waitForCounters(page, {
      open: baseline.open + 1,
      done: baseline.done + 1,
    });

    await page.click(`[data-todo-toggle="${firstId}"]`);
    await waitForCounters(page, {
      open: baseline.open,
      done: baseline.done + 2,
    });

    const pageErrors = handle.pageErrors ?? [];
    assert.equal(
      pageErrors.length,
      0,
      `client errors: ${pageErrors.map((item) => String(item)).join(" | ")}`,
    );
  } finally {
    if (typeof handle.close === "function") {
      await handle.close();
    }
  }
}

