import {
  useEffect,
  useMemo,
  useState,
  type ComponentType,
  type FormEvent,
} from "react";
import type { Context } from "cordis";
import { Check, Plus, Tag as TagIcon, Trash2, X } from "lucide-react";
import { useNavigate } from "@host/client-sdk";

interface TodoTag {
  readonly id: string;
  readonly name: string;
  readonly color: string;
  readonly createdAt: string;
}

interface TaskRef {
  readonly id: string;
  readonly title?: string;
  readonly state?: string;
}

interface ItemSlotProps {
  readonly task: TaskRef;
  readonly refresh?: () => Promise<void>;
}

interface TagState {
  tags: TodoTag[];
  assignments: Record<string, TodoTag[]>;
  error: string;
  loaded: boolean;
}

const TAG_API = "/api/app/todo-tags";
const FALLBACK_COLOR = "#64748b";
const PALETTE = [
  "#ef4444",
  "#f97316",
  "#f59e0b",
  "#10b981",
  "#06b6d4",
  "#3b82f6",
  "#8b5cf6",
  "#ec4899",
];

const tagState: TagState = {
  tags: [],
  assignments: {},
  error: "",
  loaded: false,
};

const listeners = new Set<() => void>();

function notify(): void {
  for (const listener of Array.from(listeners)) {
    listener();
  }
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const detail =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(detail);
  }
  return data as T;
}

let inflight: Promise<void> | null = null;

async function loadTagState(force = false): Promise<void> {
  if (tagState.loaded && !force) return;
  if (inflight) return inflight;

  inflight = (async () => {
    try {
      const [tagResult, assignmentResult] = await Promise.all([
        requestJson<{ tags: TodoTag[] }>(`${TAG_API}/tags`),
        requestJson<{ assignments: Record<string, TodoTag[]> }>(
          `${TAG_API}/assignments`,
        ),
      ]);
      tagState.tags = tagResult.tags ?? [];
      tagState.assignments = assignmentResult.assignments ?? {};
      tagState.error = "";
      tagState.loaded = true;
    } catch (error) {
      tagState.error = describe(error);
    } finally {
      inflight = null;
      notify();
    }
  })();

  return inflight;
}

function nextColor(): string {
  const color = PALETTE[tagState.tags.length % PALETTE.length];
  return typeof color === "string" ? color : FALLBACK_COLOR;
}

function replaceAssignments(taskId: string, tags: readonly TodoTag[]): void {
  tagState.assignments = {
    ...tagState.assignments,
    [taskId]: Array.from(tags),
  };
  notify();
}

async function createTag(name: string, color?: string): Promise<TodoTag> {
  const result = await requestJson<{
    tag: TodoTag;
    deduplicated?: boolean;
  }>(`${TAG_API}/tags`, {
    method: "POST",
    body: JSON.stringify({ name, color: color ?? nextColor() }),
  });
  // The server normalizes new names and may resolve a case-variant save to an
  // existing tag, so merge by id instead of blindly appending a duplicate.
  tagState.tags = [
    ...tagState.tags.filter((tag) => tag.id !== result.tag.id),
    result.tag,
  ].sort((left, right) => left.name.localeCompare(right.name));
  notify();
  return result.tag;
}

async function removeTag(tagId: string): Promise<void> {
  await requestJson(`${TAG_API}/tags/${encodeURIComponent(tagId)}`, {
    method: "DELETE",
  });
  tagState.tags = tagState.tags.filter((tag) => tag.id !== tagId);
  const next: Record<string, TodoTag[]> = {};
  for (const taskId of Object.keys(tagState.assignments)) {
    next[taskId] = (tagState.assignments[taskId] ?? []).filter(
      (tag) => tag.id !== tagId,
    );
  }
  tagState.assignments = next;
  notify();
}

async function setTaskTags(
  taskId: string,
  tagIds: readonly string[],
): Promise<void> {
  const result = await requestJson<{ tags: TodoTag[] }>(
    `${TAG_API}/tasks/${encodeURIComponent(taskId)}/tags`,
    { method: "PUT", body: JSON.stringify({ tagIds }) },
  );
  replaceAssignments(taskId, result.tags ?? []);
}

async function attachTag(taskId: string, tagId: string): Promise<void> {
  const result = await requestJson<{ tags: TodoTag[] }>(
    `${TAG_API}/tasks/${encodeURIComponent(taskId)}/tags`,
    { method: "POST", body: JSON.stringify({ tagId }) },
  );
  replaceAssignments(taskId, result.tags ?? []);
}

async function detachTag(taskId: string, tagId: string): Promise<void> {
  const result = await requestJson<{ tags: TodoTag[] }>(
    `${TAG_API}/tasks/${encodeURIComponent(taskId)}/tags/${encodeURIComponent(tagId)}`,
    { method: "DELETE" },
  );
  replaceAssignments(taskId, result.tags ?? []);
}

function useTagState(): TagState {
  const [, setVersion] = useState(0);

  useEffect(() => {
    const unsubscribe = subscribe(() => setVersion((value) => value + 1));
    void loadTagState();
    return unsubscribe;
  }, []);

  return tagState;
}

function TagChip({
  tag,
  onRemove,
}: {
  readonly tag: TodoTag;
  readonly onRemove?: () => void;
}) {
  return (
    <span
      data-tag-chip={tag.id}
      style={{
        borderColor: `${tag.color}55`,
        backgroundColor: `${tag.color}18`,
        color: tag.color,
      }}
      className="inline-flex max-w-[10rem] items-center gap-1 rounded-full border px-2 py-0.5 text-[11px] font-medium"
    >
      <span className="truncate">{tag.name}</span>
      {onRemove && (
        <button
          type="button"
          data-tag-remove={tag.id}
          aria-label={`移除标签：${tag.name}`}
          onClick={onRemove}
          className="inline-flex size-4 shrink-0 items-center justify-center rounded-full hover:bg-black/10"
        >
          <X className="size-3" aria-hidden="true" />
        </button>
      )}
    </span>
  );
}

function TagEditorDialog({
  taskId,
  taskTitle,
  initialTagIds,
  onClose,
}: {
  readonly taskId: string;
  readonly taskTitle: string;
  readonly initialTagIds: readonly string[];
  readonly onClose: () => void;
}) {
  const state = useTagState();
  const [selected, setSelected] = useState<string[]>(() =>
    Array.from(initialTagIds),
  );
  const [draft, setDraft] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const toggle = (tagId: string) => {
    setSelected((current) =>
      current.includes(tagId)
        ? current.filter((id) => id !== tagId)
        : [...current, tagId],
    );
  };

  const handleCreate = async (event: FormEvent) => {
    event.preventDefault();
    const name = draft.trim();
    if (!name || busy) return;
    setBusy(true);
    setError("");
    try {
      const tag = await createTag(name);
      setSelected((current) =>
        current.includes(tag.id) ? current : [...current, tag.id],
      );
      setDraft("");
    } catch (createError) {
      setError(describe(createError));
    } finally {
      setBusy(false);
    }
  };

  const handleSave = async () => {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      await setTaskTags(taskId, selected);
      onClose();
    } catch (saveError) {
      setError(describe(saveError));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center p-3 md:items-center">
      <button
        type="button"
        aria-label="关闭标签编辑"
        data-tag-editor-backdrop="true"
        onClick={onClose}
        className="absolute inset-0 h-full w-full cursor-default bg-black/35"
      />
      <div
        role="dialog"
        aria-modal="true"
        aria-label={`编辑标签：${taskTitle}`}
        data-tag-editor={taskId}
        className="relative flex w-full max-w-sm flex-col gap-3 rounded-xl border border-line bg-surface p-4 shadow-2xl"
      >
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0">
            <h3 className="truncate text-sm font-semibold text-ink">编辑标签</h3>
            <p className="truncate text-xs text-muted">{taskTitle}</p>
          </div>
          <button
            type="button"
            data-tag-editor-close="true"
            aria-label="关闭标签编辑"
            onClick={onClose}
            className="inline-flex size-8 shrink-0 items-center justify-center rounded-md text-muted transition-colors hover:bg-canvas hover:text-ink"
          >
            <X className="size-4" aria-hidden="true" />
          </button>
        </div>

        <div className="max-h-56 min-h-0 space-y-1.5 overflow-y-auto">
          {state.tags.length === 0 ? (
            <p className="rounded-md border border-dashed border-line px-3 py-4 text-center text-xs text-muted">
              还没有标签，在下方创建第一个标签
            </p>
          ) : (
            state.tags.map((tag) => {
              const isSelected = selected.includes(tag.id);
              return (
                <button
                  key={tag.id}
                  type="button"
                  data-tag-toggle={tag.id}
                  data-tag-selected={isSelected ? "true" : "false"}
                  disabled={busy}
                  onClick={() => toggle(tag.id)}
                  className={`flex w-full items-center justify-between gap-2 rounded-md border px-2.5 py-2 text-left text-sm transition-colors disabled:opacity-60 ${
                    isSelected
                      ? "border-accent bg-accent-soft text-ink"
                      : "border-line bg-canvas text-ink hover:bg-line/40"
                  }`}
                >
                  <span className="flex min-w-0 items-center gap-2">
                    <span
                      className="size-2.5 shrink-0 rounded-full"
                      style={{ backgroundColor: tag.color }}
                    />
                    <span className="truncate">{tag.name}</span>
                  </span>
                  <span
                    className={`flex size-4 shrink-0 items-center justify-center rounded border ${
                      isSelected
                        ? "border-accent bg-accent text-surface"
                        : "border-line"
                    }`}
                  >
                    {isSelected && <Check className="size-3" aria-hidden="true" />}
                  </span>
                </button>
              );
            })
          )}
        </div>

        <form
          onSubmit={(event) => void handleCreate(event)}
          className="flex items-center gap-1.5"
        >
          <input
            type="text"
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            placeholder="新建标签名称"
            aria-label="新建标签名称"
            data-tag-editor-create-input="true"
            className="min-h-9 w-full rounded-md border border-line bg-canvas px-2.5 py-1.5 text-xs text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
          />
          <button
            type="submit"
            disabled={busy || !draft.trim()}
            data-tag-editor-create-submit="true"
            aria-label="创建标签"
            className="inline-flex size-9 shrink-0 items-center justify-center rounded-md bg-accent text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
          >
            <Plus className="size-4" aria-hidden="true" />
          </button>
        </form>

        {error && (
          <p role="alert" data-tag-editor-error="true" className="text-xs text-danger">
            {error}
          </p>
        )}

        <div className="flex items-center justify-end gap-2">
          <button
            type="button"
            data-tag-editor-cancel="true"
            onClick={onClose}
