import {
  useEffect,
  useMemo,
  useState,
  type ComponentType,
  type FormEvent,
} from "react";
import type { Context } from "cordis";
import { ClipboardCheck, ClipboardList, Pencil, X } from "lucide-react";

interface ReviewTask {
  readonly id: string;
  readonly title?: string;
  readonly state?: string;
}

interface ItemSlotProps {
  readonly task: ReviewTask;
  readonly refresh?: () => Promise<void>;
}

interface ReviewItem {
  readonly id: string;
  readonly taskId: string;
  readonly taskTitle: string;
  readonly summary: string;
  readonly status: "pending" | "consumed" | "superseded";
  readonly createdAt: string;
  readonly consumedAt: string | null;
}

const REVIEW_API = "/api/app/todo-review";
const MIN_SUMMARY_LENGTH = 4;

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> { ... }

interface ReviewStoreState {
  reviews: ReviewItem[];
  loaded: boolean;
  error: string;
}

const store: ReviewStoreState = { reviews: [], loaded: false, error: "" };
const listeners = new Set<() => void>();
let inflight: Promise<void> | null = null;

function notify(): void { for (const listener of Array.from(listeners)) listener(); }
function subscribe(listener): () => void {...}

async function loadReviews(force = false): Promise<void> {
  if (store.loaded && !force) return;
  if (inflight) return inflight;
  inflight = (async () => {
    try {
      const result = await requestJson<{ reviews: ReviewItem[] }>(`${REVIEW_API}/reviews`);
      store.reviews = result.reviews ?? [];
      store.error = "";
      store.loaded = true;
    } catch (error) {
      store.error = describe(error);
    } finally {
      inflight = null;
      notify();
    }
  })();
  return inflight;
}

function sortReviews(reviews: ReviewItem[]): ReviewItem[] {
  return [...reviews].sort((left, right) => {
    if (left.createdAt === right.createdAt) return right.id.localeCompare(left.id);
    return right.createdAt.localeCompare(left.createdAt);
  });
}

function upsertReview(review: ReviewItem): void {
  store.reviews = sortReviews([review, ...store.reviews.filter((item) => item.id !== review.id)]);
  notify();
}

function useReviews(): ReviewStoreState {
  const [, setVersion] = useState(0);
  useEffect(() => {
    const unsubscribe = subscribe(() => setVersion((value) => value + 1));
    void loadReviews();
    return unsubscribe;
  }, []);
  return store;
}

function latestReviewFor(reviews: readonly ReviewItem[], taskId: string): ReviewItem | null {
  return reviews.find((review) => review.taskId === taskId) ?? null;
}

async function fetchLatestReview(taskId: string): Promise<ReviewItem | null> {
  const result = await requestJson<{ review: ReviewItem | null }>(
    `${REVIEW_API}/tasks/${encodeURIComponent(taskId)}/review`,
  );
  return result.review ?? null;
}

async function saveReview(taskId: string, summary: string): Promise<ReviewItem> {
  const result = await requestJson<{ review: ReviewItem }>(
    `${REVIEW_API}/tasks/${encodeURIComponent(taskId)}/reviews`,
    { method: "POST", body: JSON.stringify({ summary }) },
  );
  upsertReview(result.review);
  // older pending versions are superseded server-side; refresh the catalog.
  void loadReviews(true);
  return result.review;
}
```

