async function waitForGone(page: BrowserPage, selector: string, timeout = 4000): Promise<void> {
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline) {
    try {
      await page.waitForSelector(selector, { timeout: 120 });
    } catch {
      return;
    }
    await sleep(60);
  }
  throw new Error(`selector ${selector} did not disappear`);
}
```
