import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface ReviewShape {
  readonly id: string;
  readonly taskId: string;
  readonly taskTitle: string;
  readonly summary: string;
  readonly status: string;
  readonly createdAt: string;
  readonly consumedAt: string | null;
}

interface ReviewBody {
  readonly review: ReviewShape | null;
}

interface ReviewListBody {
  readonly reviews: readonly ReviewShape[];
}

function errorMessage(body: unknown): string {
  const value = (body as { error?: unknown } | null)?.error;
  return typeof value === "string" ? value : "";
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = globalThis.crypto.randomUUID().slice(0, 8);

  const createTask = async (label: string): Promise<string> => {
    const response = await ctx.request({
      method: "POST",
      path: "/api/app/todo-core/tasks",
      body: { title: `${label} ${suffix}` },
    });
    assert.equal(response.status, 201);
    return (response.body as { task: { id: string } }).task.id;
  };

  const createReview = async (taskId: string, summary: string) =>
    ctx.request({
      method: "POST",
      path: `/api/app/todo-review/tasks/${taskId}/reviews`,
      body: { summary },
    });

  const latest = async (taskId: string): Promise<ReviewShape | null> => {
    const response = await ctx.request({
      method: "GET",
      path: `/api/app/todo-review/tasks/${taskId}/review`,
    });
    assert.equal(response.status, 200);
    return (response.body as ReviewBody).review;
  };

  const taskId = await createTask("Review core task");

  // The server guard must block completion even when the client modal is
  // bypassed entirely.
  const blocked = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done" },
  });
  assert.equal(blocked.status, 422);
  assert.match(errorMessage(blocked.body), /复盘/);

  const stillOpen = await ctx.request({
    method: "GET",
    path: `/api/app/todo-core/tasks/${taskId}`,
  });
  assert.equal(stillOpen.status, 200);
  assert.equal(
    (stillOpen.body as { task: { state: string } }).task.state,
    "open",
  );

  const blank = await createReview(taskId, "   ");
  assert.equal(blank.status, 400);
  const tooShort = await createReview(taskId, "ok");
  assert.equal(tooShort.status, 400);
  const tooLong = await createReview(taskId, "复".repeat(2001));
  assert.equal(tooLong.status, 400);

  const created = await createReview(taskId, "  第一轮复盘总结  ");
  assert.equal(created.status, 201);
  const firstReview = (created.body as { review: ReviewShape }).review;
  assert.equal(firstReview.taskId, taskId);
  assert.equal(firstReview.summary, "第一轮复盘总结");
  assert.equal(firstReview.status, "pending");
  assert.equal(firstReview.consumedAt, null);
  assert.match(firstReview.taskTitle, /Review core task/);

  const otherTaskId = await createTask("Review other task");
  const otherCreated = await createReview(otherTaskId, "另一个任务的复盘");
  assert.equal(otherCreated.status, 201);
  const otherReview = (otherCreated.body as { review: ReviewShape }).review;

  // A review id belonging to another task must never unlock this task.
  const mismatched = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done", meta: { reviewId: otherReview.id } },
  });
  assert.equal(mismatched.status, 422);
  assert.match(errorMessage(mismatched.body), /不匹配|不存在/);

  const completed = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done", meta: { reviewId: firstReview.id } },
  });
  assert.equal(completed.status, 200);
  assert.equal(
    (completed.body as { task: { state: string } }).task.state,
    "done",
  );

  const consumed = await latest(taskId);
  assert.ok(consumed);
  assert.equal(consumed.id, firstReview.id);
  assert.equal(consumed.status, "consumed");
  assert.equal(typeof consumed.consumedAt, "string");

  // Reopening does not require a review, but the consumed review cannot be
  // replayed to close the task again without a fresh summary.
  const reopened = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "open" },
  });
  assert.equal(reopened.status, 200);

  const reused = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done", meta: { reviewId: firstReview.id } },
  });
  assert.equal(reused.status, 422);
  assert.match(errorMessage(reused.body), /已使用|重新填写/);

  const secondCreated = await createReview(taskId, "第二轮复盘总结");
  assert.equal(secondCreated.status, 201);
  const secondReview = (secondCreated.body as { review: ReviewShape }).review;

  // The same generic seam also validates the latest pending review when a
  // non-browser caller does not send the meta hint; validation is mandatory.
  const completedAgain = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done" },
  });
  assert.equal(completedAgain.status, 200);

  const finalLatest = await latest(taskId);
  assert.ok(finalLatest);
  assert.equal(finalLatest.id, secondReview.id);
  assert.equal(finalLatest.status, "consumed");

  const taskReviews = await ctx.request({
    method: "GET",
    path: `/api/app/todo-review/tasks/${taskId}/reviews`,
  });
  assert.equal(taskReviews.status, 200);
  const history = (taskReviews.body as ReviewListBody).reviews;
  assert.deepEqual(
    history.map((review) => review.id).sort(),
    [firstReview.id, secondReview.id].sort(),
  );
  assert.ok(history.every((review) => review.status === "consumed"));

  const catalog = await ctx.request({
    method: "GET",
    path: "/api/app/todo-review/reviews",
  });
  assert.equal(catalog.status, 200);
  const catalogIds = (catalog.body as ReviewListBody).reviews.map(
    (review) => review.id,
  );
  assert.ok(catalogIds.includes(firstReview.id));
  assert.ok(catalogIds.includes(secondReview.id));

  const unknownTask = await createReview(
    "task-does-not-exist",
    "无效任务复盘",
  );
  assert.equal(unknownTask.status, 404);
}

testFiles.todo-review.ui.spec.ts:
import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface BrowserPage {
  readonly waitForSelector: (
    selector: string,
    options?: { readonly timeout?: number },
  ) => Promise<unknown>;
  readonly textContent: (selector: string) => Promise<string | null>;
  readonly getAttribute: (
    selector: string,
    name: string,
  ) => Promise<string | null>;
  readonly click: (selector: string) => Promise<unknown>;
}

interface BrowserHandle {
  readonly page: BrowserPage;
  readonly pageErrors?: readonly unknown[];
  readonly close?: () => Promise<unknown>;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function waitForGone(
  page: BrowserPage,
  selector: string,
  timeout = 5000,
): Promise<void> {
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline) {
    try {
      await page.waitForSelector(selector, { timeout: 150 });
    } catch {
      return;
    }
    await sleep(60);
  }
  throw new Error(`selector ${selector} was still present`);
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = globalThis.crypto.randomUUID().slice(0, 8);

  const createTask = async (label: string): Promise<string> => {
    const response = await ctx.request({
      method: "POST",
      path: "/api/app/todo-core/tasks",
      body: { title: `${label} ${suffix}` },
    });
    assert.equal(response.status, 201);
    return (response.body as { task: { id: string } }).task.id;
  };

  const firstTaskId = await createTask("Review UI task");
  const seeded = await ctx.request({
    method: "POST",
    path: `/api/app/todo-review/tasks/${firstTaskId}/reviews`,
    body: { summary: `UI 复盘总结 ${suffix}` },
  });
  assert.equal(seeded.status, 201);

  const secondTaskId = await createTask("Review UI cancel task");

  const openPage = ctx.openBrowserPage as unknown as (
    target?: string,
  ) => Promise<BrowserHandle>;
  const handle = await openPage("/");
  const page = handle.page;

  try {
    await page.waitForSelector(`[data-todo-item="${firstTaskId}"]`, {
      timeout: 8000,
    });
    await page.waitForSelector(
      `[data-todo-review-badge="${firstTaskId}"][data-todo-review-status="pending"]`,
      { timeout: 8000 },
    );

    // Toggling the core checkbox must open the review modal instead of
    // completing the task. The pre-seeded summary also proves the dialog is
    // prefilled from the server, so submitting needs no typing.
    await page.click(`[data-todo-toggle="${firstTaskId}"]`);
    await page.waitForSelector('[data-todo-review-dialog="true"]', {
      timeout: 8000,
    });

    const stateWhileDialog = await page.getAttribute(
      `[data-todo-item="${firstTaskId}"]`,
      "data-todo-state",
    );
    assert.equal(stateWhileDialog, "open");

    await page.click('[data-todo-review-submit="true"]');
    await waitForGone(page, '[data-todo-review-dialog="true"]');

    // Done tasks leave the default "open" filter, so switch to all to observe
    // the persisted state and the refreshed review badge.
    await page.click('[data-todo-filter="all"]');
    await page.waitForSelector(
      `[data-todo-item="${firstTaskId}"][data-todo-state="done"]`,
      { timeout: 8000 },
    );
    await page.waitForSelector(
      `[data-todo-review-badge="${firstTaskId}"][data-todo-review-status="consumed"]`,
      { timeout: 8000 },
    );

    const latest = await ctx.request({
      method: "GET",
      path: `/api/app/todo-review/tasks/${firstTaskId}/review`,
    });
    assert.equal(latest.status, 200);
    const review = (
      latest.body as {
        review: { status: string; summary: string } | null;
      }
    ).review;
    assert.ok(review);
    assert.equal(review.status, "consumed");
    assert.match(review.summary, new RegExp(suffix));

    // Cancelling the modal must abort the transition and surface the core
    // error banner so the task stays open.
    await page.click(`[data-todo-toggle="${secondTaskId}"]`);
    await page.waitForSelector('[data-todo-review-dialog="true"]', {
      timeout: 8000,
    });
    await page.click('[data-todo-review-cancel="true"]');
    await waitForGone(page, '[data-todo-review-dialog="true"]');
    await page.waitForSelector('[data-todo-error="true"]', {
      timeout: 8000,
    });

    const cancelledState = await page.getAttribute(
      `[data-todo-item="${secondTaskId}"]`,
      "data-todo-state",
    );
    assert.equal(cancelledState, "open");

    const pageErrors = handle.pageErrors ?? [];
    assert.equal(
      pageErrors.length,
      0,
      `client errors: ${pageErrors.map((item) => String(item)).join(" | ")}`,
    );
  } finally {
    if (typeof handle.close === "function") {
      await handle.close();
    }
  }
}

