import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface CounterStats {
  readonly open: number;
  readonly done: number;
  readonly total: number;
}

interface StatsBody {
  readonly stats: CounterStats;
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const readStats = async (): Promise<CounterStats> => {
    const response = await ctx.request({
      method: "GET",
      path: "/api/app/todo-counter/stats",
    });
    assert.equal(response.status, 200);
    const stats = (response.body as StatsBody).stats;
    assert.equal(typeof stats.open, "number");
    assert.equal(typeof stats.done, "number");
    assert.equal(stats.total, stats.open + stats.done);
    return stats;
  };

  const before = await readStats();
  const suffix = globalThis.crypto.randomUUID().slice(0, 8);

  const created = await ctx.request({
    method: "POST",
    path: "/api/app/todo-core/tasks",
    body: { title: `Counter Task ${suffix}` },
  });
  assert.equal(created.status, 201);
  const taskId = (created.body as { task: { id: string } }).task.id;

  const afterCreate = await readStats();
  assert.equal(afterCreate.open, before.open + 1);
  assert.equal(afterCreate.done, before.done);

  const done = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done" },
  });
  assert.equal(done.status, 200);

  const afterDone = await readStats();
  assert.equal(afterDone.open, before.open);
  assert.equal(afterDone.done, before.done + 1);
  assert.equal(afterDone.total, before.total + 1);
}

