function registerTransitionGuard(ctx: Context): void {
  ctx.on("todo:before-transition", async (payload) => {
    if (payload.nextState !== "done") return;

    const task = payload.task;
    const submitted = await openReviewDialog({
      taskId: task.id,
      taskTitle: task.title,
      submitLabel: "提交并完成",
      onSubmit: async (summary) => {
        const review = await saveReview(task.id, summary);
        try {
          const holder = payload as { meta?: Record<string, unknown> };
          const meta = isRecord(holder.meta) ? holder.meta : {};
          meta.reviewId = review.id;
          holder.meta = meta;
        } catch {
          // The server falls back to the latest pending review for this task.
        }
      },
    });

    if (!submitted) {
      return "已取消完成：完成任务前必须填写复盘总结";
    }

    // The review is consumed by the server guard once the transition persists.
    globalThis.setTimeout(() => { void loadReviews(true); }, 500);
    return;
  });
}
