import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface ReviewShape {
  readonly id: string;
  readonly taskId: string;
  readonly taskTitle: string;
  readonly summary: string;
  readonly status: string;
  readonly createdAt: string;
  readonly consumedAt: string | null;
}

interface ReviewBody { readonly review: ReviewShape | null }
interface ReviewListBody { readonly reviews: readonly ReviewShape[] }

function errorMessage(body: unknown): string {
  const value = (body as { error?: unknown } | null)?.error;
  return typeof value === "string" ? value : "";
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = globalThis.crypto.randomUUID().slice(0, 8);

  const createTask = async (label: string): Promise<string> => {
    const response = await ctx.request({
      method: "POST",
      path: "/api/app/todo-core/tasks",
      body: { title: `${label} ${suffix}` },
    });
    assert.equal(response.status, 201);
    return (response.body as { task: { id: string } }).task.id;
  };

  const createReview = async (taskId: string, summary: string) =>
    ctx.request({
      method: "POST",
      path: `/api/app/todo-review/tasks/${taskId}/reviews`,
      body: { summary },
    });

  const latest = async (taskId: string): Promise<ReviewShape | null> => {
    const response = await ctx.request({
      method: "GET",
      path: `/api/app/todo-review/tasks/${taskId}/review`,
    });
    assert.equal(response.status, 200);
    return (response.body as ReviewBody).review;
  };

  const taskId = await createTask("Review core task");

  const blocked = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done" },
  });
  assert.equal(blocked.status, 422);
  assert.match(errorMessage(blocked.body), /复盘/);

  const openTask = await ctx.request({
    method: "GET",
    path: `/api/app/todo-core/tasks/${taskId}`,
  });
  assert.equal(openTask.status, 200);
  assert.equal((openTask.body as { task: { state: string } }).task.state, "open");

  const blank = await createReview(taskId, "   ");
  assert.equal(blank.status, 400);
  const tooShort = await createReview(taskId, "ok");
  assert.equal(tooShort.status, 400);
  const tooLong = await createReview(taskId, "复".repeat(2001));
  assert.equal(tooLong.status, 400);

  const created = await createReview(taskId, "  第一轮复盘总结  ");
  assert.equal(created.status, 201);
  const firstReview = (created.body as { review: ReviewShape }).review;
  assert.equal(firstReview.taskId, taskId);
  assert.equal(firstReview.summary, "第一轮复盘总结");
  assert.equal(firstReview.status, "pending");
  assert.equal(firstReview.consumedAt, null);
  assert.match(firstReview.taskTitle, /Review core task/);

  const otherTaskId = await createTask("Review other task");
  const otherCreated = await createReview(otherTaskId, "另一个任务的复盘");
  assert.equal(otherCreated.status, 201);
  const otherReview = (otherCreated.body as { review: ReviewShape }).review;

  const mismatched = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done", meta: { reviewId: otherReview.id } },
  });
  assert.equal(mismatched.status, 422);
  assert.match(errorMessage(mismatched.body), /不匹配|不存在/);

  const completed = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done", meta: { reviewId: firstReview.id } },
  });
  assert.equal(completed.status, 200);
  assert.equal(
    (completed.body as { task: { state: string } }).task.state,
    "done",
  );

  const consumed = await latest(taskId);
  assert.ok(consumed);
  assert.equal(consumed.id, firstReview.id);
  assert.equal(consumed.status, "consumed");
  assert.equal(typeof consumed.consumedAt, "string");

  const reopened = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "open" },
  });
  assert.equal(reopened.status, 200);

  const reused = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done", meta: { reviewId: firstReview.id } },
  });
  assert.equal(reused.status, 422);
  assert.match(errorMessage(reused.body), /已使用|重新填写/);

  const secondCreated = await createReview(taskId, "第二轮复盘总结");
  assert.equal(secondCreated.status, 201);
  const secondReview = (secondCreated.body as { review: ReviewShape }).review;

  // The generic server seam also accepts the latest pending review without
  // any meta hint, so non-browser clients cannot bypass but can cooperate.
  const completedAgain = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done" },
  });
  assert.equal(completedAgain.status, 200);

  const finalLatest = await latest(taskId);
  assert.ok(finalLatest);
  assert.equal(finalLatest.id, secondReview.id);
  assert.equal(finalLatest.status, "consumed");

  const taskReviews = await ctx.request({
    method: "GET",
    path: `/api/app/todo-review/tasks/${taskId}/reviews`,
  });
  assert.equal(taskReviews.status, 200);
  const history = (taskReviews.body as ReviewListBody).reviews;
  assert.deepEqual(
    history.map((review) => review.id).sort(),
    [firstReview.id, secondReview.id].sort(),
  );
  assert.ok(history.every((review) => review.status === "consumed"));

  const catalog = await ctx.request({
    method: "GET",
    path: "/api/app/todo-review/reviews",
  });
  assert.equal(catalog.status, 200);
  const catalogIds = (catalog.body as ReviewListBody).reviews.map((r) => r.id);
  assert.ok(catalogIds.includes(firstReview.id));
  assert.ok(catalogIds.includes(secondReview.id));

  const unknownTask = await createReview("task-does-not-exist", "无效任务复盘");
  assert.equal(unknownTask.status, 404);
}
