", "sourceFiles": {"server.ts": "import { Service, type Context } from "cordis";
import type { ScopedDb } from "@host/server-sdk";
import type {
  CreateTodoReviewInput,
  TodoReview,
  TodoReviewService,
} from "./contract.d.ts";

const MIN_SUMMARY_LENGTH = 4;
const MAX_SUMMARY_LENGTH = 2000;

interface ReviewRow {
  readonly id: string;
  readonly task_id: string;
  readonly task_title: string;
  readonly summary: string;
  readonly status: string;
  readonly created_at: string;
  readonly consumed_at: string | null;
}

interface TaskLike {
  readonly id: string;
  readonly title: string;
  readonly state: string;
}

interface TodoLookup {
  get(id: string): TaskLike | null;
}

interface TransitionPayload {
  readonly task: TaskLike;
  readonly nextState: "open" | "done";
  readonly meta?: Record<string, unknown>;
}

interface HttpResponse {
  readonly status: number;
  readonly body: Record<string, unknown>;
}

function toReview(row: ReviewRow): TodoReview {
  const status =
    row.status === "consumed"
      ? "consumed"
      : row.status === "superseded"
        ? "superseded"
        : "pending";
  return {
    id: row.id,
    taskId: row.task_id,
    taskTitle: row.task_title,
    summary: row.summary,
    status,
    createdAt: row.created_at,
    consumedAt: row.consumed_at,
  };
}

function httpError(status: number, message: string): Error & { status: number } {
  const error = new Error(message) as Error & { status: number };
  error.status = status;
  return error;
}

/**
 * Reviews are always trimmed before persistence so whitespace-only summaries
 * can never satisfy the completion guard.
 */
function normalizeSummary(value: unknown): string {
  const summary = typeof value === "string" ? value.trim() : "";
  if (!summary) {
    throw httpError(400, "Review summary is required");
  }
  if (summary.length < MIN_SUMMARY_LENGTH) {
    throw httpError(
      400,
      `Review summary must be at least ${MIN_SUMMARY_LENGTH} characters`,
    );
  }
  if (summary.length > MAX_SUMMARY_LENGTH) {
    throw httpError(
      400,
      `Review summary must be at most ${MAX_SUMMARY_LENGTH} characters`,
    );
  }
  return summary;
}

function toErrorResponse(error: unknown): HttpResponse {
  const status = (error as { status?: unknown } | null)?.status;
  const message = error instanceof Error ? error.message : String(error);
  return {
    status:
      typeof status === "number" && status >= 400 && status < 600
        ? status
        : 500,
    body: { error: message.length > 0 ? message : "Unexpected error" },
  };
}

/**
 * Review extension for todo-core.
 *
 * The plugin never modifies todo-core's storage. It cooperates through the
 * generic `todo:before-transition` seam: the browser collects a summary and
 * forwards its id in `meta`, while the server guard independently verifies the
 * review before allowing a task to become `done`.
 */
export default class TodoReviewPlugin
  extends Service
  implements TodoReviewService
{
  private readonly db: ScopedDb;
  private readonly approvedReviews = new Map<string, string>();

  constructor(ctx: Context) {
    super(ctx, "todoReview");
    this.db = ctx.db;

    this.db.exec(`
      CREATE TABLE IF NOT EXISTS plg_todo_review__reviews (
        id TEXT PRIMARY KEY,
        task_id TEXT NOT NULL,
        task_title TEXT NOT NULL,
        summary TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending',
        created_at TEXT NOT NULL,
        consumed_at TEXT
      )
    `);

    this.db.exec(`
      CREATE INDEX IF NOT EXISTS idx_plg_todo_review__reviews_task
        ON plg_todo_review__reviews (task_id, created_at)
    `);

    ctx.on("todo:before-transition", (payload) =>
      this.guardTransition(payload),
    );
    ctx.on("todo:changed", (task) =>
      this.archiveApprovedReview(task.id, task.state),
    );

    ctx.http.route("GET", "/reviews", () => ({ reviews: this.list() }));

    ctx.http.route("GET", "/reviews/:id", (req) => {
      const review = this.get(req.params.id);
      if (!review) {
        return { status: 404, body: { error: "Review not found" } };
      }
      return { review };
    });

    ctx.http.route("GET", "/tasks/:taskId/review", (req) => {
      const task = this.resolveTask(req.params.taskId);
      if (!task) {
        return { status: 404, body: { error: "Task not found" } };
      }
      return { review: this.latestForTask(req.params.taskId) };
    });

    ctx.http.route("GET", "/tasks/:taskId/reviews", (req) => {
      const task = this.resolveTask(req.params.taskId);
      if (!task) {
        return { status: 404, body: { error: "Task not found" } };
      }
      return { reviews: this.listForTask(req.params.taskId) };
    });

    ctx.http.route("POST", "/tasks/:taskId/reviews", (req) => {
      const body = (req.body ?? {}) as { summary?: unknown };
      try {
        const review = this.create(req.params.taskId, {
          summary: typeof body.summary === "string" ? body.summary : "",
        });
        return { status: 201, body: { review } };
      } catch (error) {
        return toErrorResponse(error);
      }
    });
  }

  list(): TodoReview[] {
    const rows = this.db
      .prepare(
        "SELECT id, task_id, task_title, summary, status, created_at, consumed_at FROM plg_todo_review__reviews ORDER BY created_at DESC, id DESC",
      )
      .all<ReviewRow>();
    return rows.map(toReview);
  }

  get(id: string): TodoReview | null {
    const row = this.db
      .prepare(
        "SELECT id, task_id, task_title, summary, status, created_at, consumed_at FROM plg_todo_review__reviews WHERE id = ?",
      )
      .get<ReviewRow>(id);
    return row ? toReview(row) : null;
  }

  listForTask(taskId: string): TodoReview[] {
    const rows = this.db
      .prepare(
        "SELECT id, task_id, task_title, summary, status, created_at, consumed_at FROM plg_todo_review__reviews WHERE task_id = ? ORDER BY created_at DESC, id DESC",
      )
      .all<ReviewRow>(taskId);
    return rows.map(toReview);
  }

  latestForTask(taskId: string): TodoReview | null {
    const row = this.db
      .prepare(
        "SELECT id, task_id, task_title, summary, status, created_at, consumed_at FROM plg_todo_review__reviews WHERE task_id = ? ORDER BY created_at DESC, id DESC LIMIT 1",
      )
      .get<ReviewRow>(taskId);
    return row ? toReview(row) : null;
  }

  pendingForTask(taskId: string): TodoReview | null {
    const row = this.db
      .prepare(
        "SELECT id, task_id, task_title, summary, status, created_at, consumed_at FROM plg_todo_review__reviews WHERE task_id = ? AND status = 'pending' ORDER BY created_at DESC, id DESC LIMIT 1",
      )
      .get<ReviewRow>(taskId);
    return row ? toReview(row) : null;
  }

  create(
    taskId: string,
    input: string | CreateTodoReviewInput,
  ): TodoReview {
    const task = this.resolveTask(taskId);
    if (!task) {
      throw httpError(404, "Task not found");
    }

    const summary = normalizeSummary(
      typeof input === "string" ? input : input.summary,
    );
    const now = new Date().toISOString();
    const id = globalThis.crypto.randomUUID();

    // A task keeps at most one active review; saving a newer summary replaces
    // any older draft while keeping it in history as superseded.
    this.db
      .prepare(
        "UPDATE plg_todo_review__reviews SET status = 'superseded' WHERE task_id = ? AND status = 'pending'",
      )
      .run(taskId);

    this.db
      .prepare(
        "INSERT INTO plg_todo_review__reviews (id, task_id, task_title, summary, status, created_at, consumed_at) VALUES (?, ?, ?, ?, 'pending', ?, NULL)",
      )
      .run(id, taskId, task.title, summary, now);

    const created = this.get(id)!;
    this.ctx.emit("todo-review:changed", {
      kind: "review-created",
      review: created,
    });
    return created;
  }

  consume(id: string): TodoReview | null {
    const existing = this.get(id);
    if (!existing || existing.status !== "pending") return null;

    const result = this.db
      .prepare(
        "UPDATE plg_todo_review__reviews SET status = 'consumed', consumed_at = ? WHERE id = ? AND status = 'pending'",
      )
      .run(new Date().toISOString(), id);
    if (Number(result.changes) === 0) return null;

    const consumed = this.get(id)!;
    this.ctx.emit("todo-review:changed", {
      kind: "review-consumed",
      review: consumed,
    });
    return consumed;
  }

  /**
   * Server-side enforcement. Runs inside todo-core's generic bail seam before
   * the task state is persisted, so direct HTTP callers cannot skip a review.
   */
  private guardTransition(payload: TransitionPayload): void | string {
    if (payload.nextState !== "done") return;

    const taskId = payload.task.id;
    const requestedId = payload.meta?.reviewId;
    let review: TodoReview | null;

    if (typeof requestedId === "string" && requestedId.trim().length > 0) {
      review = this.get(requestedId);
      if (!review || review.taskId !== taskId) {
        return "复盘总结不存在或与当前任务不匹配";
      }
      if (review.status !== "pending") {
        return "复盘总结已使用或已失效，请重新填写后再完成任务";
      }
    } else {
      // Non-browser callers may omit the meta hint; the latest pending review
      // still has to exist and pass the same validation below.
      review = this.pendingForTask(taskId);
    }

    if (!review) {
      return "完成任务前必须填写复盘总结";
    }

    const summary = review.summary.trim();
    if (summary.length < MIN_SUMMARY_LENGTH) {
      return `复盘总结至少需要 ${MIN_SUMMARY_LENGTH} 个字`;
    }
    if (summary.length > MAX_SUMMARY_LENGTH) {
      return `复盘总结最多 ${MAX_SUMMARY_LENGTH} 个字`;
    }

    // Remember the approved review; it is archived only after todo-core emits
    // `todo:changed` with the persisted done state, so a later bail cannot burn
    // a review without completing the task.
    this.approvedReviews.set(taskId, review.id);
    return;
  }

  private archiveApprovedReview(taskId: string, state: string): void {
    if (state !== "done") return;

    const approvedId = this.approvedReviews.get(taskId);
    this.approvedReviews.delete(taskId);

    const review = approvedId
      ? this.get(approvedId)
      : this.pendingForTask(taskId);
    if (review && review.status === "pending") {
      this.consume(review.id);
    }
  }

  private resolveTodo(): TodoLookup | null {
    try {
      const direct = (this.ctx as unknown as { todo?: TodoLookup }).todo;
      if (direct && typeof direct.get === "function") return direct;
    } catch {
      // todo service is not available in this composition
    }

    try {
      const get = (this.ctx as unknown as { get?: (name: string) => unknown })
        .get;
      if (typeof get === "function") {
        const resolved = get.call(this.ctx, "todo") as TodoLookup | undefined;
        if (resolved && typeof resolved.get === "function") return resolved;
      }
    } catch {
      // todo service is not available in this composition
    }

    return null;
  }

  private resolveTask(taskId: string): TaskLike | null {
    const todo = this.resolveTodo();
    if (!todo) return null;
    try {
      return todo.get(taskId) ?? null;
    } catch {
      return null;
    }
  }
}
", "client.tsx": "import {
  useEffect,
  useState,
  type ComponentType,
  type FormEvent,
} from "react";
import type { Context } from "cordis";
import { ClipboardCheck, ClipboardList, Pencil, X } from "lucide-react";

interface ReviewTask {
  readonly id: string;
  readonly title?: string;
  readonly state?: string;
}

interface ItemSlotProps {
  readonly task: ReviewTask;
  readonly refresh?: () => Promise<void>;
}

interface ReviewItem {
  readonly id: string;
  readonly taskId: string;
  readonly taskTitle: string;
  readonly summary: string;
  readonly status: "pending" | "consumed" | "superseded";
  readonly createdAt: string;
  readonly consumedAt: string | null;
}

const REVIEW_API = "/api/app/todo-review";
const MIN_SUMMARY_LENGTH = 4;
const MAX_SUMMARY_LENGTH = 2000;

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

interface ReviewStore {
  reviews: ReviewItem[];
  loaded: boolean;
  error: string;
}

const reviewStore: ReviewStore = { reviews: [], loaded: false, error: "" };
const reviewListeners = new Set<() => void>();
let reviewInflight: Promise<void> | null = null;

function notifyReviews(): void {
  for (const listener of Array.from(reviewListeners)) {
    listener();
  }
}

function subscribeReviews(listener: () => void): () => void {
  reviewListeners.add(listener);
  return () => {
    reviewListeners.delete(listener);
  };
}

function sortReviews(reviews: readonly ReviewItem[]): ReviewItem[] {
  return [...reviews].sort((left, right) => {
    if (left.createdAt === right.createdAt) {
      return right.id.localeCompare(left.id);
    }
    return right.createdAt.localeCompare(left.createdAt);
  });
}

async function loadReviews(force = false): Promise<void> {
  if (reviewStore.loaded && !force) return;
  if (reviewInflight) return reviewInflight;

  reviewInflight = (async () => {
    try {
      const result = await requestJson<{ reviews: ReviewItem[] }>(
        `${REVIEW_API}/reviews`,
      );
      reviewStore.reviews = sortReviews(result.reviews ?? []);
      reviewStore.error = "";
      reviewStore.loaded = true;
    } catch (error) {
      reviewStore.error = describe(error);
    } finally {
      reviewInflight = null;
      notifyReviews();
    }
  })();

  return reviewInflight;
}

function upsertReview(review: ReviewItem): void {
  reviewStore.reviews = sortReviews([
    review,
    ...reviewStore.reviews.filter((item) => item.id !== review.id),
  ]);
  notifyReviews();
}

function useReviews(): ReviewStore {
  const [, setVersion] = useState(0);

  useEffect(() => {
    const listener = () => setVersion((value) => value + 1);
    reviewListeners.add(listener);
    void loadReviews();
    return () => {
      reviewListeners.delete(listener);
    };
  }, []);

  return reviewStore;
}

function latestReviewFor(
  reviews: readonly ReviewItem[],
  taskId: string,
): ReviewItem | null {
  return reviews.find((review) => review.taskId === taskId) ?? null;
}

async function fetchLatestReview(taskId: string): Promise<ReviewItem | null> {
  const result = await requestJson<{ review: ReviewItem | null }>(
    `${REVIEW_API}/tasks/${encodeURIComponent(taskId)}/review`,
  );
  return result.review ?? null;
}

async function saveReview(
  taskId: string,
  summary: string,
): Promise<ReviewItem> {
  // Reuse an identical pending summary instead of duplicating history when a
  // dialog was prefilled from an earlier save.
  try {
    const latest = await fetchLatestReview(taskId);
    if (latest && latest.status === "pending" && latest.summary === summary) {
      return latest;
    }
  } catch {
    // Fall through to creating a fresh review.
  }

  const result = await requestJson<{ review: ReviewItem }>(
    `${REVIEW_API}/tasks/${encodeURIComponent(taskId)}/reviews`,
    { method: "POST", body: JSON.stringify({ summary }) },
  );
  upsertReview(result.review);
  // The server supersedes older drafts, so refresh the catalog in the
  // background to keep badges and history in sync.
  void loadReviews(true);
  return result.review;
}

interface DialogOptions {
  readonly taskId: string;
  readonly taskTitle: string;
  readonly submitLabel: string;
  readonly onSubmit: (summary: string) => Promise<void>;
}

interface ActiveDialog extends DialogOptions {
  readonly id: string;
  readonly initialSummary: string;
  readonly close: (submitted: boolean) => void;
}

let activeDialog: ActiveDialog | null = null;
let dialogSeq = 0;
const dialogListeners = new Set<() => void>();

function notifyDialog(): void {
  for (const listener of Array.from(dialogListeners)) {
    listener();
  }
}

function useActiveDialog(): ActiveDialog | null {
  const [, setVersion] = useState(0);

  useEffect(() => {
    const listener = () => setVersion((value) => value + 1);
    dialogListeners.add(listener);
    return () => {
      dialogListeners.delete(listener);
    };
  }, []);

  return activeDialog;
}

async function openReviewDialog(options: DialogOptions): Promise<boolean> {
  if (activeDialog) return false;

  let initialSummary = "";
  try {
    const latest = await fetchLatestReview(options.taskId);
    initialSummary = latest?.summary ?? "";
  } catch {
    // Keep the dialog usable; server-side validation remains authoritative.
  }

  if (activeDialog) return false;

  return new Promise<boolean>((resolve) => {
    activeDialog = {
      ...options,
      id: `review-dialog-${++dialogSeq}`,
      initialSummary,
      close: (submitted) => {
        if (!activeDialog) return;
        activeDialog = null;
        notifyDialog();
        resolve(submitted);
      },
    };
    notifyDialog();
  });
}

function ReviewDialogForm({ dialog }: { readonly dialog: ActiveDialog }) {
  const [summary, setSummary] = useState(dialog.initialSummary);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const trimmed = summary.trim();

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault();
    if (busy) return;
    if (trimmed.length < MIN_SUMMARY_LENGTH) {
      setError(`复盘总结至少需要 ${MIN_SUMMARY_LENGTH} 个字`);
      return;
    }
    setBusy(true);
    setError("");
    try {
      await dialog.onSubmit(trimmed);
      dialog.close(true);
    } catch (submitError) {
      setError(describe(submitError));
      setBusy(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center p-3 md:items-center">
      <button
        type="button"
        aria-label="关闭复盘弹窗"
        data-todo-review-backdrop="true"
        onClick={() => {
          if (!busy) dialog.close(false);
        }}
        className="absolute inset-0 h-full w-full cursor-default bg-black/40"
      />
      <form
        role="dialog"
        aria-modal="true"
        aria-label={`填写复盘总结：${dialog.taskTitle}`}
        data-todo-review-dialog="true"
        data-todo-review-task={dialog.taskId}
        onSubmit={(event) => void handleSubmit(event)}
        className="relative flex w-full max-w-md flex-col gap-3 rounded-xl border border-line bg-surface p-4 shadow-2xl"
      >
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0">
            <h2 className="text-sm font-semibold text-ink">完成前复盘</h2>
            <p className="truncate text-xs text-muted">{dialog.taskTitle}</p>
          </div>
          <button
            type="button"
            data-todo-review-close="true"
            aria-label="关闭复盘弹窗"
            disabled={busy}
            onClick={() => dialog.close(false)}
            className="inline-flex size-11 shrink-0 items-center justify-center rounded-md text-muted transition-colors hover:bg-canvas hover:text-ink disabled:opacity-50 md:size-8"
          >
            <X className="size-4" aria-hidden="true" />
          </button>
        </div>

        <p className="rounded-md border border-line bg-canvas px-3 py-2 text-xs text-muted">
          完成任务前必须填写复盘总结；提交后会由服务端校验，并随完成动作归档。
        </p>

        <div className="space-y-1.5">
          <label
            htmlFor="todo-review-summary-input"
            className="block text-xs font-medium text-muted"
          >
            复盘总结
          </label>
          <textarea
            id="todo-review-summary-input"
            data-todo-review-input="true"
            rows={5}
            maxLength={MAX_SUMMARY_LENGTH}
            value={summary}
            onChange={(event) => setSummary(event.target.value)}
            placeholder="记录完成情况、收获与后续改进…"
            className="w-full resize-none rounded-md border border-line bg-surface px-3 py-2 text-sm text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
          />
          <p className="text-[11px] text-muted">
            至少 {MIN_SUMMARY_LENGTH} 个字，最多 {MAX_SUMMARY_LENGTH} 个字。
          </p>
        </div>

        {error && (
          <p
            role="alert"
            data-todo-review-error="true"
            className="text-xs text-danger"
          >
            {error}
          </p>
        )}

        <div className="flex items-center justify-end gap-2">
          <button
            type="button"
            data-todo-review-cancel="true"
            disabled={busy}
            onClick={() => dialog.close(false)}
            className="inline-flex min-h-10 items-center justify-center rounded-md border border-line bg-surface px-3 text-sm text-ink transition-colors hover:bg-canvas disabled:opacity-50"
          >
            取消
          </button>
          <button
            type="submit"
            data-todo-review-submit="true"
            disabled={busy || trimmed.length < MIN_SUMMARY_LENGTH}
            className="inline-flex min-h-10 items-center justify-center rounded-md bg-accent px-3.5 text-sm font-medium text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
          >
            {busy ? "提交中…" : dialog.submitLabel}
          </button>
        </div>
      </form>
    </div>
  );
}

function ReviewDialogHost() {
  const dialog = useActiveDialog();
  if (!dialog) return null;
  return <ReviewDialogForm key={dialog.id} dialog={dialog} />;
}

function reviewTone(status: ReviewItem["status"] | "missing"): string {
  if (status === "consumed") {
    return "border-accent/30 bg-accent-soft text-accent";
  }
  if (status === "pending") {
    return "border-line bg-canvas text-ink";
  }
  return "border-dashed border-line bg-canvas text-muted";
}

function ReviewBadges({ task }: ItemSlotProps) {
  const state = useReviews();
  const latest = latestReviewFor(state.reviews, task.id);
  const status = latest?.status ?? "missing";
  const label =
    status === "consumed"
      ? "已复盘"
      : status === "pending"
        ? "待复盘"
        : status === "superseded"
          ? "复盘已更新"
          : "未复盘";

  return (
    <span
      data-todo-review-badge={task.id}
      data-todo-review-status={status}
