    </span>
  );
}

function ReviewDetail({ task }: ItemSlotProps) {
  const state = useReviews();
  const latest = latestReviewFor(state.reviews, task.id);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const handleEdit = async () => {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      await openReviewDialog({
        taskId: task.id,
        taskTitle: task.title ?? task.id,
        submitLabel: "保存复盘",
        onSubmit: async (summary) => {
          await saveReview(task.id, summary);
        },
      });
    } catch (editError) {
      setError(describe(editError));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div data-todo-review-detail={task.id} className="space-y-2">
      <div className="flex items-center justify-between gap-2">
        <h3 className="text-xs font-medium text-muted">复盘总结</h3>
        <button
          type="button"
          data-todo-review-edit={task.id}
          disabled={busy}
          onClick={() => void handleEdit()}
          className="inline-flex items-center gap-1 rounded-md border border-line bg-surface px-2 py-1 text-[11px] text-muted transition-colors hover:border-accent hover:text-accent disabled:opacity-50"
        >
          <Pencil className="size-3" aria-hidden="true" />
          <span>{latest ? "编辑复盘" : "填写复盘"}</span>
        </button>
      </div>

      {latest ? (
        <>
          <p
            data-todo-review-summary={task.id}
            className="whitespace-pre-wrap rounded-md border border-line bg-canvas px-3 py-2 text-sm text-ink"
          >
            {latest.summary}
          </p>
          <p className="text-[11px] text-muted">
            {latest.status === "consumed"
              ? "已随任务完成归档"
              : latest.status === "pending"
                ? "已保存，完成时自动归档"
                : "已被更新的复盘替代"}
          </p>
        </>
      ) : (
        <p className="text-xs text-muted">
          该任务还没有复盘总结，完成任务前会弹窗要求填写。
        </p>
      )}

      {state.error && <p className="text-[11px] text-danger">{state.error}</p>}
      {error && (
        <p
          role="alert"
          data-todo-review-detail-error="true"
          className="text-xs text-danger"
        >
          {error}
        </p>
      )}
    </div>
  );
}

/**
 * Client half of the generic dual-end interception seam. todo-core dispatches
 * `todo:before-transition` before it calls the transition endpoint, so this
 * extension can collect the review summary in a modal and hand its id to the
 * server through the opaque `meta` channel.
 */
function registerTransitionGuard(ctx: Context): void {
  ctx.on("todo:before-transition", async (payload) => {
    if (payload.nextState !== "done") return;

    const task = payload.task;
    const submitted = await openReviewDialog({
      taskId: task.id,
      taskTitle: task.title,
      submitLabel: "提交并完成",
      onSubmit: async (summary) => {
        const review = await saveReview(task.id, summary);
        const holder = payload as { meta?: Record<string, unknown> };
        const meta =
          holder.meta && typeof holder.meta === "object" ? holder.meta : {};
        meta.reviewId = review.id;
        try {
          holder.meta = meta;
        } catch {
          // The server falls back to the latest pending review for this task.
        }
      },
    });

    if (!submitted) {
      return "已取消完成：完成任务前必须填写复盘总结";
    }

    // todo-core consumes the review once the transition is persisted; refresh
    // the badge shortly afterwards so the new status is reflected.
    globalThis.setTimeout(() => {
      void loadReviews(true);
    }, 500);
    return;
  });
}

type AnyFunction = (arg: unknown, second?: unknown, third?: unknown) => unknown;

function pick(source: unknown, key: string): unknown {
  try {
    if (!source || typeof source !== "object") return undefined;
    return (source as Record<string, unknown>)[key];
  } catch {
    return undefined;
  }
}

function registerSlot<P>(
  ctx: Context,
  name: string,
  component: ComponentType<P>,
  order: number,
): void {
  const holders: unknown[] = [
    pick(ctx, "slot"),
    pick(ctx, "slots"),
    pick(pick(ctx, "router"), "slot"),
    pick(pick(ctx, "router"), "slots"),
    pick(pick(ctx, "ui"), "slot"),
    pick(pick(ctx, "ui"), "slots"),
    pick(pick(ctx, "client"), "slot"),
    pick(pick(ctx, "client"), "slots"),
  ];

  for (const holder of holders) {
    if (!holder) continue;

    const registrars: unknown[] = [];
    if (typeof holder === "function") {
      registrars.push(holder);
    } else if (typeof holder === "object") {
      const api = holder as { register?: unknown; add?: unknown };
      if (typeof api.register === "function") registrars.push(api.register);
      if (typeof api.add === "function") registrars.push(api.add);
    }

    for (const registrar of registrars) {
      const register = registrar as AnyFunction;
      const objectForm = () => register.call(holder, { name, order, component });
      const argsForm = () => register.call(holder, name, component, { order });
      const attempts =
        register.length >= 2 ? [argsForm, objectForm] : [objectForm, argsForm];

      for (const attempt of attempts) {
        try {
          attempt();
          return;
        } catch {
          // try the next registration shape
        }
      }
    }
  }
}

export default function apply(ctx: Context): void {
  registerTransitionGuard(ctx);

  // todo.header.actions is mounted for the whole todo workspace, so the
  // dialog host can present a fixed overlay no matter which task is toggled.
  registerSlot(ctx, "todo.header.actions", ReviewDialogHost, 90);
  registerSlot(ctx, "todo.item.badges", ReviewBadges, 30);
  registerSlot(ctx, "todo.item.detail", ReviewDetail, 40);
}
"}, "testFiles": {"todo-review.spec.ts": "import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface ReviewShape {
  readonly id: string;
  readonly taskId: string;
  readonly taskTitle: string;
  readonly summary: string;
  readonly status: string;
  readonly createdAt: string;
  readonly consumedAt: string | null;
}

interface ReviewBody {
  readonly review: ReviewShape | null;
}

interface ReviewListBody {
  readonly reviews: readonly ReviewShape[];
}

function errorMessage(body: unknown): string {
  const value = (body as { error?: unknown } | null)?.error;
  return typeof value === "string" ? value : "";
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = globalThis.crypto.randomUUID().slice(0, 8);

  const createTask = async (label: string): Promise<string> => {
    const response = await ctx.request({
      method: "POST",
      path: "/api/app/todo-core/tasks",
      body: { title: `${label} ${suffix}` },
    });
    assert.equal(response.status, 201);
    return (response.body as { task: { id: string } }).task.id;
  };

  const createReview = async (taskId: string, summary: string) =>
    ctx.request({
      method: "POST",
      path: `/api/app/todo-review/tasks/${taskId}/reviews`,
      body: { summary },
    });

  const latest = async (taskId: string): Promise<ReviewShape | null> => {
    const response = await ctx.request({
      method: "GET",
      path: `/api/app/todo-review/tasks/${taskId}/review`,
    });
    assert.equal(response.status, 200);
    return (response.body as ReviewBody).review;
  };

  const taskId = await createTask("Review core task");

  // The server guard must block completion even when the client modal is
  // bypassed entirely.
  const blocked = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done" },
  });
  assert.equal(blocked.status, 422);
  assert.match(errorMessage(blocked.body), /复盘/);

  const stillOpen = await ctx.request({
    method: "GET",
    path: `/api/app/todo-core/tasks/${taskId}`,
  });
  assert.equal(stillOpen.status, 200);
  assert.equal(
    (stillOpen.body as { task: { state: string } }).task.state,
    "open",
  );

  const blank = await createReview(taskId, "   ");
  assert.equal(blank.status, 400);
  const tooShort = await createReview(taskId, "ok");
  assert.equal(tooShort.status, 400);
  const tooLong = await createReview(taskId, "复".repeat(2001));
  assert.equal(tooLong.status, 400);

  const created = await createReview(taskId, "  第一轮复盘总结  ");
  assert.equal(created.status, 201);
  const firstReview = (created.body as { review: ReviewShape }).review;
  assert.equal(firstReview.taskId, taskId);
  assert.equal(firstReview.summary, "第一轮复盘总结");
  assert.equal(firstReview.status, "pending");
  assert.equal(firstReview.consumedAt, null);
  assert.match(firstReview.taskTitle, /Review core task/);

  const otherTaskId = await createTask("Review other task");
  const otherCreated = await createReview(otherTaskId, "另一个任务的复盘");
  assert.equal(otherCreated.status, 201);
  const otherReview = (otherCreated.body as { review: ReviewShape }).review;

  // A review id belonging to another task must never unlock this task.
  const mismatched = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done", meta: { reviewId: otherReview.id } },
  });
  assert.equal(mismatched.status, 422);
  assert.match(errorMessage(mismatched.body), /不匹配|不存在/);

  const completed = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done", meta: { reviewId: firstReview.id } },
  });
  assert.equal(completed.status, 200);
  assert.equal(
    (completed.body as { task: { state: string } }).task.state,
    "done",
  );

  const consumed = await latest(taskId);
  assert.ok(consumed);
  assert.equal(consumed.id, firstReview.id);
  assert.equal(consumed.status, "consumed");
  assert.equal(typeof consumed.consumedAt, "string");

  // Reopening does not require a review, but the consumed review cannot be
  // replayed to close the task again without a fresh summary.
  const reopened = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "open" },
  });
  assert.equal(reopened.status, 200);

  const reused = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done", meta: { reviewId: firstReview.id } },
  });
  assert.equal(reused.status, 422);
  assert.match(errorMessage(reused.body), /已使用|重新填写/);

  const secondCreated = await createReview(taskId, "第二轮复盘总结");
  assert.equal(secondCreated.status, 201);
  const secondReview = (secondCreated.body as { review: ReviewShape }).review;

  // The same generic seam also validates the latest pending review when a
  // non-browser caller does not send the meta hint; validation is mandatory.
  const completedAgain = await ctx.request({
    method: "POST",
    path: `/api/app/todo-core/tasks/${taskId}/transition`,
    body: { nextState: "done" },
  });
  assert.equal(completedAgain.status, 200);

  const finalLatest = await latest(taskId);
  assert.ok(finalLatest);
  assert.equal(finalLatest.id, secondReview.id);
  assert.equal(finalLatest.status, "consumed");

  const taskReviews = await ctx.request({
    method: "GET",
    path: `/api/app/todo-review/tasks/${taskId}/reviews`,
  });
  assert.equal(taskReviews.status, 200);
  const history = (taskReviews.body as ReviewListBody).reviews;
  assert.deepEqual(
    history.map((review) => review.id).sort(),
    [firstReview.id, secondReview.id].sort(),
  );
  assert.ok(history.every((review) => review.status === "consumed"));

  const catalog = await ctx.request({
    method: "GET",
