            aria-label="新建标签名称"
            data-todo-tags-create-input="true"
            className="min-h-10 w-full max-w-sm rounded-md border border-line bg-surface px-3 py-2 text-sm text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
          />
          <button
            type="submit"
            disabled={busy || !draft.trim()}
            data-todo-tags-create-submit="true"
            className="inline-flex min-h-10 shrink-0 items-center justify-center rounded-md bg-accent px-4 text-sm font-medium text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
          >
            创建标签
