import { Service, type Context } from "cordis";
import type { ScopedDb } from "@host/server-sdk";
import type {
  CreateTodoReviewInput,
  TodoReview,
  TodoReviewService,
} from "./contract.d.ts";

const MIN_SUMMARY_LENGTH = 4;
const MAX_SUMMARY_LENGTH = 2000;

interface ReviewRow {
  readonly id: string;
  readonly task_id: string;
  readonly task_title: string;
  readonly summary: string;
  readonly status: string;
  readonly created_at: string;
  readonly consumed_at: string | null;
}

interface TaskLike {
  readonly id: string;
  readonly title: string;
  readonly state: string;
}

interface TodoLookup {
  get(id: string): TaskLike | null;
}

interface TransitionPayload {
  readonly task: TaskLike;
  readonly nextState: "open" | "done";
  readonly meta?: Record<string, unknown>;
}

interface HttpResponse {
  readonly status: number;
  readonly body: Record<string, unknown>;
}

function toReview(row: ReviewRow): TodoReview {
  const status =
    row.status === "consumed"
      ? "consumed"
      : row.status === "superseded"
        ? "superseded"
        : "pending";
  return {
    id: row.id,
    taskId: row.task_id,
    taskTitle: row.task_title,
    summary: row.summary,
    status,
    createdAt: row.created_at,
    consumedAt: row.consumed_at,
  };
}

function httpError(status: number, message: string): Error & { status: number } {
  const error = new Error(message) as Error & { status: number };
  error.status = status;
  return error;
}

/**
 * Reviews are always trimmed before persistence so whitespace-only summaries
 * can never satisfy the completion guard.
 */
function normalizeSummary(value: unknown): string {
  const summary = typeof value === "string" ? value.trim() : "";
  if (!summary) {
    throw httpError(400, "Review summary is required");
  }
  if (summary.length < MIN_SUMMARY_LENGTH) {
    throw httpError(
      400,
      `Review summary must be at least ${MIN_SUMMARY_LENGTH} characters`,
    );
  }
  if (summary.length > MAX_SUMMARY_LENGTH) {
    throw httpError(
      400,
      `Review summary must be at most ${MAX_SUMMARY_LENGTH} characters`,
    );
  }
  return summary;
}

function toErrorResponse(error: unknown): HttpResponse {
  const status = (error as { status?: unknown } | null)?.status;
  const message = error instanceof Error ? error.message : String(error);
  return {
    status:
      typeof status === "number" && status >= 400 && status < 600
        ? status
        : 500,
    body: { error: message.length > 0 ? message : "Unexpected error" },
  };
}

/**
 * Review extension for todo-core.
 *
 * The plugin never modifies todo-core's storage. It cooperates through the
 * generic `todo:before-transition` seam: the browser collects a summary and
 * forwards its id in `meta`, while the server guard independently verifies the
 * review before allowing a task to become `done`.
 */
export default class TodoReviewPlugin
  extends Service
  implements TodoReviewService
{
  private readonly db: ScopedDb;
  private readonly approvedReviews = new Map<string, string>();

  constructor(ctx: Context) {
    super(ctx, "todoReview");
    this.db = ctx.db;

    this.db.exec(`
      CREATE TABLE IF NOT EXISTS plg_todo_review__reviews (
        id TEXT PRIMARY KEY,
        task_id TEXT NOT NULL,
        task_title TEXT NOT NULL,
        summary TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'pending',
        created_at TEXT NOT NULL,
        consumed_at TEXT
      )
    `);

    this.db.exec(`
      CREATE INDEX IF NOT EXISTS idx_plg_todo_review__reviews_task
        ON plg_todo_review__reviews (task_id, created_at)
    `);

    ctx.on("todo:before-transition", (payload) =>
      this.guardTransition(payload),
    );
    ctx.on("todo:changed", (task) =>
      this.archiveApprovedReview(task.id, task.state),
    );

    ctx.http.route("GET", "/reviews", () => ({ reviews: this.list() }));

    ctx.http.route("GET", "/reviews/:id", (req) => {
      const review = this.get(req.params.id);
      if (!review) {
        return { status: 404, body: { error: "Review not found" } };
      }
      return { review };
    });

    ctx.http.route("GET", "/tasks/:taskId/review", (req) => {
      const task = this.resolveTask(req.params.taskId);
      if (!task) {
        return { status: 404, body: { error: "Task not found" } };
      }
      return { review: this.latestForTask(req.params.taskId) };
    });

    ctx.http.route("GET", "/tasks/:taskId/reviews", (req) => {
      const task = this.resolveTask(req.params.taskId);
      if (!task) {
        return { status: 404, body: { error: "Task not found" } };
      }
      return { reviews: this.listForTask(req.params.taskId) };
    });

    ctx.http.route("POST", "/tasks/:taskId/reviews", (req) => {
      const body = (req.body ?? {}) as { summary?: unknown };
      try {
        const review = this.create(req.params.taskId, {
          summary: typeof body.summary === "string" ? body.summary : "",
        });
        return { status: 201, body: { review } };
      } catch (error) {
        return toErrorResponse(error);
      }
    });
  }

  list(): TodoReview[] {
    const rows = this.db
      .prepare(
        "SELECT id, task_id, task_title, summary, status, created_at, consumed_at FROM plg_todo_review__reviews ORDER BY created_at DESC, id DESC",
      )
      .all<ReviewRow>();
    return rows.map(toReview);
  }

  get(id: string): TodoReview | null {
    const row = this.db
      .prepare(
        "SELECT id, task_id, task_title, summary, status, created_at, consumed_at FROM plg_todo_review__reviews WHERE id = ?",
      )
      .get<ReviewRow>(id);
    return row ? toReview(row) : null;
  }

  listForTask(taskId: string): TodoReview[] {
    const rows = this.db
      .prepare(
        "SELECT id, task_id, task_title, summary, status, created_at, consumed_at FROM plg_todo_review__reviews WHERE task_id = ? ORDER BY created_at DESC, id DESC",
      )
      .all<ReviewRow>(taskId);
    return rows.map(toReview);
  }

  latestForTask(taskId: string): TodoReview | null {
    const row = this.db
      .prepare(
        "SELECT id, task_id, task_title, summary, status, created_at, consumed_at FROM plg_todo_review__reviews WHERE task_id = ? ORDER BY created_at DESC, id DESC LIMIT 1",
      )
      .get<ReviewRow>(taskId);
    return row ? toReview(row) : null;
  }

  pendingForTask(taskId: string): TodoReview | null {
    const row = this.db
      .prepare(
        "SELECT id, task_id, task_title, summary, status, created_at, consumed_at FROM plg_todo_review__reviews WHERE task_id = ? AND status = 'pending' ORDER BY created_at DESC, id DESC LIMIT 1",
      )
      .get<ReviewRow>(taskId);
    return row ? toReview(row) : null;
  }

  create(
    taskId: string,
    input: string | CreateTodoReviewInput,
  ): TodoReview {
    const task = this.resolveTask(taskId);
    if (!task) {
      throw httpError(404, "Task not found");
    }

    const summary = normalizeSummary(
      typeof input === "string" ? input : input.summary,
    );
    const now = new Date().toISOString();
    const id = globalThis.crypto.randomUUID();

    // A task keeps at most one active review; saving a newer summary replaces
    // any older draft while keeping it in history as superseded.
    this.db
      .prepare(
        "UPDATE plg_todo_review__reviews SET status = 'superseded' WHERE task_id = ? AND status = 'pending'",
      )
      .run(taskId);

    this.db
      .prepare(
        "INSERT INTO plg_todo_review__reviews (id, task_id, task_title, summary, status, created_at, consumed_at) VALUES (?, ?, ?, ?, 'pending', ?, NULL)",
      )
      .run(id, taskId, task.title, summary, now);

    const created = this.get(id)!;
    this.ctx.emit("todo-review:changed", {
      kind: "review-created",
      review: created,
    });
    return created;
  }

  consume(id: string): TodoReview | null {
    const existing = this.get(id);
    if (!existing || existing.status !== "pending") return null;

    const result = this.db
      .prepare(
        "UPDATE plg_todo_review__reviews SET status = 'consumed', consumed_at = ? WHERE id = ? AND status = 'pending'",
      )
      .run(new Date().toISOString(), id);
    if (Number(result.changes) === 0) return null;

    const consumed = this.get(id)!;
    this.ctx.emit("todo-review:changed", {
      kind: "review-consumed",
      review: consumed,
    });
    return consumed;
  }

  /**
   * Server-side enforcement. Runs inside todo-core's generic bail seam before
   * the task state is persisted, so direct HTTP callers cannot skip a review.
   */
  private guardTransition(payload: TransitionPayload): void | string {
    if (payload.nextState !== "done") return;

    const taskId = payload.task.id;
    const requestedId = payload.meta?.reviewId;
    let review: TodoReview | null;

    if (typeof requestedId === "string" && requestedId.trim().length > 0) {
      review = this.get(requestedId);
      if (!review || review.taskId !== taskId) {
        return "复盘总结不存在或与当前任务不匹配";
      }
      if (review.status !== "pending") {
        return "复盘总结已使用或已失效，请重新填写后再完成任务";
      }
    } else {
      // Non-browser callers may omit the meta hint; the latest pending review
      // still has to exist and pass the same validation below.
      review = this.pendingForTask(taskId);
    }

    if (!review) {
      return "完成任务前必须填写复盘总结";
    }

    const summary = review.summary.trim();
    if (summary.length < MIN_SUMMARY_LENGTH) {
      return `复盘总结至少需要 ${MIN_SUMMARY_LENGTH} 个字`;
    }
    if (summary.length > MAX_SUMMARY_LENGTH) {
      return `复盘总结最多 ${MAX_SUMMARY_LENGTH} 个字`;
    }

    // Remember the approved review; it is archived only after todo-core emits
    // `todo:changed` with the persisted done state, so a later bail cannot burn
    // a review without completing the task.
    this.approvedReviews.set(taskId, review.id);
    return;
  }

  private archiveApprovedReview(taskId: string, state: string): void {
    if (state !== "done") return;

    const approvedId = this.approvedReviews.get(taskId);
    this.approvedReviews.delete(taskId);

    const review = approvedId
      ? this.get(approvedId)
      : this.pendingForTask(taskId);
    if (review && review.status === "pending") {
      this.consume(review.id);
    }
  }

  private resolveTodo(): TodoLookup | null {
    try {
      const direct = (this.ctx as unknown as { todo?: TodoLookup }).todo;
      if (direct && typeof direct.get === "function") return direct;
    } catch {
      // todo service is not available in this composition
    }

    try {
      const get = (this.ctx as unknown as { get?: (name: string) => unknown })
        .get;
      if (typeof get === "function") {
        const resolved = get.call(this.ctx, "todo") as TodoLookup | undefined;
        if (resolved && typeof resolved.get === "function") return resolved;
      }
    } catch {
      // todo service is not available in this composition
    }

    return null;
  }

  private resolveTask(taskId: string): TaskLike | null {
    const todo = this.resolveTodo();
    if (!todo) return null;
    try {
      return todo.get(taskId) ?? null;
    } catch {
      return null;
    }
  }
}

