import { Service, type Context } from "cordis";
import type {} from "@host/server-sdk";
import type { TodoCounterService, TodoCounterStats } from "./contract.d.ts";

interface TodoTaskLike {
  readonly state?: string;
}

interface TodoLookup {
  list(filter?: { readonly state?: "open" | "done" }): ReadonlyArray<TodoTaskLike>;
}

const EMPTY_STATS: TodoCounterStats = { open: 0, done: 0, total: 0 };

function countTasks(tasks: ReadonlyArray<TodoTaskLike>): TodoCounterStats {
  let open = 0;
  let done = 0;
  for (const task of tasks) {
    if (task?.state === "done") done += 1;
    else open += 1;
  }
  return { open, done, total: open + done };
}

export default class TodoCounterPlugin
  extends Service
  implements TodoCounterService
{
  constructor(ctx: Context) {
    super(ctx, "todoCounter");

    ctx.http.route("GET", "/stats", () => ({ stats: this.stats() }));
  }

  stats(): TodoCounterStats {
    const todo = this.resolveTodo();
    if (!todo) return EMPTY_STATS;
    try {
      return countTasks(todo.list());
    } catch {
      return EMPTY_STATS;
    }
  }

  private resolveTodo(): TodoLookup | null {
    try {
      const direct = (this.ctx as unknown as { todo?: unknown }).todo;
      if (direct && typeof (direct as TodoLookup).list === "function") {
        return direct as TodoLookup;
      }
    } catch {
      // todo service is not available in this composition
    }

    try {
      const get = (this.ctx as unknown as { get?: (name: string) => unknown })
        .get;
      if (typeof get === "function") {
        const resolved = get.call(this.ctx, "todo") as unknown;
        if (resolved && typeof (resolved as TodoLookup).list === "function") {
          return resolved as TodoLookup;
        }
      }
    } catch {
      // todo service is not available in this composition
    }

    return null;
  }
}

