import {
  useEffect,
  useState,
  type ComponentType,
  type FormEvent,
} from "react";
import type { Context } from "cordis";
import { ClipboardCheck, ClipboardList, Pencil, X } from "lucide-react";

interface ReviewTask {
  readonly id: string;
  readonly title?: string;
  readonly state?: string;
}

interface ItemSlotProps {
  readonly task: ReviewTask;
  readonly refresh?: () => Promise<void>;
}

interface ReviewItem {
  readonly id: string;
  readonly taskId: string;
  readonly taskTitle: string;
  readonly summary: string;
  readonly status: "pending" | "consumed" | "superseded";
  readonly createdAt: string;
  readonly consumedAt: string | null;
}

const REVIEW_API = "/api/app/todo-review";
const MIN_SUMMARY_LENGTH = 4;
const MAX_SUMMARY_LENGTH = 2000;

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const message =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(message);
  }
  return data as T;
}

interface ReviewStore {
  reviews: ReviewItem[];
  loaded: boolean;
  error: string;
}

const reviewStore: ReviewStore = { reviews: [], loaded: false, error: "" };
const reviewListeners = new Set<() => void>();
let reviewInflight: Promise<void> | null = null;

function notifyReviews(): void {
  for (const listener of Array.from(reviewListeners)) {
    listener();
  }
}

function subscribeReviews(listener: () => void): () => void {
  reviewListeners.add(listener);
  return () => {
    reviewListeners.delete(listener);
  };
}

function sortReviews(reviews: readonly ReviewItem[]): ReviewItem[] {
  return [...reviews].sort((left, right) => {
    if (left.createdAt === right.createdAt) {
      return right.id.localeCompare(left.id);
    }
    return right.createdAt.localeCompare(left.createdAt);
  });
}

async function loadReviews(force = false): Promise<void> {
  if (reviewStore.loaded && !force) return;
  if (reviewInflight) return reviewInflight;

  reviewInflight = (async () => {
    try {
      const result = await requestJson<{ reviews: ReviewItem[] }>(
        `${REVIEW_API}/reviews`,
      );
      reviewStore.reviews = sortReviews(result.reviews ?? []);
      reviewStore.error = "";
      reviewStore.loaded = true;
    } catch (error) {
      reviewStore.error = describe(error);
    } finally {
      reviewInflight = null;
      notifyReviews();
    }
  })();

  return reviewInflight;
}

function upsertReview(review: ReviewItem): void {
  reviewStore.reviews = sortReviews([
    review,
    ...reviewStore.reviews.filter((item) => item.id !== review.id),
  ]);
  notifyReviews();
}

function useReviews(): ReviewStore {
  const [, setVersion] = useState(0);

  useEffect(() => {
    const listener = () => setVersion((value) => value + 1);
    reviewListeners.add(listener);
    void loadReviews();
    return () => {
      reviewListeners.delete(listener);
    };
  }, []);

  return reviewStore;
}

function latestReviewFor(
  reviews: readonly ReviewItem[],
  taskId: string,
): ReviewItem | null {
  return reviews.find((review) => review.taskId === taskId) ?? null;
}

async function fetchLatestReview(taskId: string): Promise<ReviewItem | null> {
  const result = await requestJson<{ review: ReviewItem | null }>(
    `${REVIEW_API}/tasks/${encodeURIComponent(taskId)}/review`,
  );
  return result.review ?? null;
}

async function saveReview(
  taskId: string,
  summary: string,
): Promise<ReviewItem> {
  // Reuse an identical pending summary instead of duplicating history when a
  // dialog was prefilled from an earlier save.
  try {
    const latest = await fetchLatestReview(taskId);
    if (latest && latest.status === "pending" && latest.summary === summary) {
      return latest;
    }
  } catch {
    // Fall through to creating a fresh review.
  }

  const result = await requestJson<{ review: ReviewItem }>(
    `${REVIEW_API}/tasks/${encodeURIComponent(taskId)}/reviews`,
    { method: "POST", body: JSON.stringify({ summary }) },
  );
  upsertReview(result.review);
  // The server supersedes older drafts, so refresh the catalog in the
  // background to keep badges and history in sync.
  void loadReviews(true);
  return result.review;
}

interface DialogOptions {
  readonly taskId: string;
  readonly taskTitle: string;
  readonly submitLabel: string;
  readonly onSubmit: (summary: string) => Promise<void>;
}

interface ActiveDialog extends DialogOptions {
  readonly id: string;
  readonly initialSummary: string;
  readonly close: (submitted: boolean) => void;
}

let activeDialog: ActiveDialog | null = null;
let dialogSeq = 0;
const dialogListeners = new Set<() => void>();

function notifyDialog(): void {
  for (const listener of Array.from(dialogListeners)) {
    listener();
  }
}

function useActiveDialog(): ActiveDialog | null {
  const [, setVersion] = useState(0);

  useEffect(() => {
    const listener = () => setVersion((value) => value + 1);
    dialogListeners.add(listener);
    return () => {
      dialogListeners.delete(listener);
    };
  }, []);

  return activeDialog;
}

async function openReviewDialog(options: DialogOptions): Promise<boolean> {
  if (activeDialog) return false;

  let initialSummary = "";
  try {
    const latest = await fetchLatestReview(options.taskId);
    initialSummary = latest?.summary ?? "";
  } catch {
    // Keep the dialog usable; server-side validation remains authoritative.
  }

  if (activeDialog) return false;

  return new Promise<boolean>((resolve) => {
    activeDialog = {
      ...options,
      id: `review-dialog-${++dialogSeq}`,
      initialSummary,
      close: (submitted) => {
        if (!activeDialog) return;
        activeDialog = null;
        notifyDialog();
        resolve(submitted);
      },
    };
    notifyDialog();
  });
}

function ReviewDialogForm({ dialog }: { readonly dialog: ActiveDialog }) {
  const [summary, setSummary] = useState(dialog.initialSummary);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const trimmed = summary.trim();

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault();
    if (busy) return;
    if (trimmed.length < MIN_SUMMARY_LENGTH) {
      setError(`复盘总结至少需要 ${MIN_SUMMARY_LENGTH} 个字`);
      return;
    }
    setBusy(true);
    setError("");
    try {
      await dialog.onSubmit(trimmed);
      dialog.close(true);
    } catch (submitError) {
      setError(describe(submitError));
      setBusy(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center p-3 md:items-center">
      <button
        type="button"
        aria-label="关闭复盘弹窗"
        data-todo-review-backdrop="true"
        onClick={() => {
          if (!busy) dialog.close(false);
        }}
        className="absolute inset-0 h-full w-full cursor-default bg-black/40"
      />
      <form
        role="dialog"
        aria-modal="true"
        aria-label={`填写复盘总结：${dialog.taskTitle}`}
        data-todo-review-dialog="true"
        data-todo-review-task={dialog.taskId}
        onSubmit={(event) => void handleSubmit(event)}
        className="relative flex w-full max-w-md flex-col gap-3 rounded-xl border border-line bg-surface p-4 shadow-2xl"
      >
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0">
            <h2 className="text-sm font-semibold text-ink">完成前复盘</h2>
            <p className="truncate text-xs text-muted">{dialog.taskTitle}</p>
          </div>
          <button
            type="button"
            data-todo-review-close="true"
            aria-label="关闭复盘弹窗"
            disabled={busy}
            onClick={() => dialog.close(false)}
            className="inline-flex size-11 shrink-0 items-center justify-center rounded-md text-muted transition-colors hover:bg-canvas hover:text-ink disabled:opacity-50 md:size-8"
          >
            <X className="size-4" aria-hidden="true" />
          </button>
        </div>

        <p className="rounded-md border border-line bg-canvas px-3 py-2 text-xs text-muted">
          完成任务前必须填写复盘总结；提交后会由服务端校验，并随完成动作归档。
        </p>

        <div className="space-y-1.5">
          <label
            htmlFor="todo-review-summary-input"
            className="block text-xs font-medium text-muted"
          >
            复盘总结
          </label>
          <textarea
            id="todo-review-summary-input"
            data-todo-review-input="true"
            rows={5}
            maxLength={MAX_SUMMARY_LENGTH}
            value={summary}
            onChange={(event) => setSummary(event.target.value)}
            placeholder="记录完成情况、收获与后续改进…"
            className="w-full resize-none rounded-md border border-line bg-surface px-3 py-2 text-sm text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
          />
          <p className="text-[11px] text-muted">
            至少 {MIN_SUMMARY_LENGTH} 个字，最多 {MAX_SUMMARY_LENGTH} 个字。
          </p>
        </div>

        {error && (
          <p
            role="alert"
            data-todo-review-error="true"
            className="text-xs text-danger"
          >
            {error}
          </p>
        )}

        <div className="flex items-center justify-end gap-2">
          <button
            type="button"
            data-todo-review-cancel="true"
            disabled={busy}
            onClick={() => dialog.close(false)}
            className="inline-flex min-h-10 items-center justify-center rounded-md border border-line bg-surface px-3 text-sm text-ink transition-colors hover:bg-canvas disabled:opacity-50"
          >
            取消
          </button>
          <button
            type="submit"
            data-todo-review-submit="true"
            disabled={busy || trimmed.length < MIN_SUMMARY_LENGTH}
            className="inline-flex min-h-10 items-center justify-center rounded-md bg-accent px-3.5 text-sm font-medium text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
          >
            {busy ? "提交中…" : dialog.submitLabel}
          </button>
        </div>
      </form>
    </div>
  );
}

function ReviewDialogHost() {
  const dialog = useActiveDialog();
  if (!dialog) return null;
  return <ReviewDialogForm key={dialog.id} dialog={dialog} />;
}

function reviewTone(status: ReviewItem["status"] | "missing"): string {
  if (status === "consumed") {
    return "border-accent/30 bg-accent-soft text-accent";
  }
  if (status === "pending") {
    return "border-line bg-canvas text-ink";
  }
  return "border-dashed border-line bg-canvas text-muted";
}

function ReviewBadges({ task }: ItemSlotProps) {
  const state = useReviews();
  const latest = latestReviewFor(state.reviews, task.id);
  const status = latest?.status ?? "missing";
  const label =
    status === "consumed"
      ? "已复盘"
      : status === "pending"
        ? "待复盘"
        : status === "superseded"
          ? "复盘已更新"
          : "未复盘";

  return (
    <span
      data-todo-review-badge={task.id}
      data-todo-review-status={status}
      title={status === "missing" ? "完成任务前需要填写复盘总结" : "复盘总结状态"}
      className={`inline-flex shrink-0 items-center gap-1 rounded-full border px-2 py-0.5 text-[11px] font-medium ${reviewTone(status)}`}
    >
      {status === "consumed" ? (
        <ClipboardCheck className="size-3" aria-hidden="true" />
      ) : (
        <ClipboardList className="size-3" aria-hidden="true" />
      )}
      <span>{label}</span>
    </span>
  );
}

function ReviewDetail({ task }: ItemSlotProps) {
  const state = useReviews();
  const latest = latestReviewFor(state.reviews, task.id);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const handleEdit = async () => {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      await openReviewDialog({
        taskId: task.id,
        taskTitle: task.title ?? task.id,
        submitLabel: "保存复盘",
        onSubmit: async (summary) => {
          await saveReview(task.id, summary);
        },
      });
    } catch (editError) {
      setError(describe(editError));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div data-todo-review-detail={task.id} className="space-y-2">
      <div className="flex items-center justify-between gap-2">
        <h3 className="text-xs font-medium text-muted">复盘总结</h3>
        <button
          type="button"
          data-todo-review-edit={task.id}
          disabled={busy}
          onClick={() => void handleEdit()}
          className="inline-flex items-center gap-1 rounded-md border border-line bg-surface px-2 py-1 text-[11px] text-muted transition-colors hover:border-accent hover:text-accent disabled:opacity-50"
        >
          <Pencil className="size-3" aria-hidden="true" />
          <span>{latest ? "编辑复盘" : "填写复盘"}</span>
        </button>
      </div>

      {latest ? (
        <>
          <p
            data-todo-review-summary={task.id}
            className="whitespace-pre-wrap rounded-md border border-line bg-canvas px-3 py-2 text-sm text-ink"
          >
            {latest.summary}
          </p>
          <p className="text-[11px] text-muted">
            {latest.status === "consumed"
              ? "已随任务完成归档"
              : latest.status === "pending"
                ? "已保存，完成时自动归档"
                : "已被更新的复盘替代"}
          </p>
        </>
      ) : (
        <p className="text-xs text-muted">
          该任务还没有复盘总结，完成任务前会弹窗要求填写。
        </p>
      )}

      {state.error && <p className="text-[11px] text-danger">{state.error}</p>}
      {error && (
        <p
          role="alert"
          data-todo-review-detail-error="true"
          className="text-xs text-danger"
        >
          {error}
        </p>
      )}
    </div>
  );
}

/**
 * Client half of the generic dual-end interception seam. todo-core dispatches
 * `todo:before-transition` before it calls the transition endpoint, so this
 * extension can collect the review summary in a modal and hand its id to the
 * server through the opaque `meta` channel.
 */
function registerTransitionGuard(ctx: Context): void {
  ctx.on("todo:before-transition", async (payload) => {
    if (payload.nextState !== "done") return;

    const task = payload.task;
    const submitted = await openReviewDialog({
      taskId: task.id,
      taskTitle: task.title,
      submitLabel: "提交并完成",
      onSubmit: async (summary) => {
        const review = await saveReview(task.id, summary);
        const holder = payload as { meta?: Record<string, unknown> };
        const meta =
          holder.meta && typeof holder.meta === "object" ? holder.meta : {};
        meta.reviewId = review.id;
        try {
          holder.meta = meta;
        } catch {
          // The server falls back to the latest pending review for this task.
        }
      },
    });

    if (!submitted) {
      return "已取消完成：完成任务前必须填写复盘总结";
    }

    // todo-core consumes the review once the transition is persisted; refresh
    // the badge shortly afterwards so the new status is reflected.
    globalThis.setTimeout(() => {
      void loadReviews(true);
    }, 500);
    return;
  });
}

type AnyFunction = (arg: unknown, second?: unknown, third?: unknown) => unknown;

function pick(source: unknown, key: string): unknown {
  try {
    if (!source || typeof source !== "object") return undefined;
    return (source as Record<string, unknown>)[key];
  } catch {
    return undefined;
  }
}

function registerSlot<P>(
  ctx: Context,
  name: string,
  component: ComponentType<P>,
  order: number,
): void {
  const holders: unknown[] = [
    pick(ctx, "slot"),
    pick(ctx, "slots"),
    pick(pick(ctx, "router"), "slot"),
    pick(pick(ctx, "router"), "slots"),
    pick(pick(ctx, "ui"), "slot"),
    pick(pick(ctx, "ui"), "slots"),
    pick(pick(ctx, "client"), "slot"),
    pick(pick(ctx, "client"), "slots"),
  ];

  for (const holder of holders) {
    if (!holder) continue;

    const registrars: unknown[] = [];
    if (typeof holder === "function") {
      registrars.push(holder);
    } else if (typeof holder === "object") {
      const api = holder as { register?: unknown; add?: unknown };
      if (typeof api.register === "function") registrars.push(api.register);
      if (typeof api.add === "function") registrars.push(api.add);
    }

    for (const registrar of registrars) {
      const register = registrar as AnyFunction;
      const objectForm = () => register.call(holder, { name, order, component });
      const argsForm = () => register.call(holder, name, component, { order });
      const attempts =
        register.length >= 2 ? [argsForm, objectForm] : [objectForm, argsForm];

      for (const attempt of attempts) {
        try {
          attempt();
          return;
        } catch {
          // try the next registration shape
        }
      }
    }
  }
}

export default function apply(ctx: Context): void {
  registerTransitionGuard(ctx);

  // todo.header.actions is mounted for the whole todo workspace, so the
  // dialog host can present a fixed overlay no matter which task is toggled.
  registerSlot(ctx, "todo.header.actions", ReviewDialogHost, 90);
  registerSlot(ctx, "todo.item.badges", ReviewBadges, 30);
  registerSlot(ctx, "todo.item.detail", ReviewDetail, 40);
}

