import assert from "node:assert/strict";
import type { PluginTestContext } from "@host/server-sdk";

interface BrowserPage {
  readonly waitForSelector: (
    selector: string,
    options?: { readonly timeout?: number },
  ) => Promise<unknown>;
  readonly textContent: (selector: string) => Promise<string | null>;
  readonly getAttribute: (
    selector: string,
    name: string,
  ) => Promise<string | null>;
  readonly click: (selector: string) => Promise<unknown>;
}

interface BrowserHandle {
  readonly page: BrowserPage;
  readonly pageErrors?: readonly unknown[];
  readonly close?: () => Promise<unknown>;
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function waitForGone(
  page: BrowserPage,
  selector: string,
  timeout = 5000,
): Promise<void> {
  const deadline = Date.now() + timeout;
  while (Date.now() < deadline) {
    try {
      await page.waitForSelector(selector, { timeout: 150 });
    } catch {
      return;
    }
    await sleep(60);
  }
  throw new Error(`selector ${selector} was still present`);
}

export default async function (ctx: PluginTestContext): Promise<void> {
  const suffix = globalThis.crypto.randomUUID().slice(0, 8);

  const createTask = async (label: string): Promise<string> => {
    const response = await ctx.request({
      method: "POST",
      path: "/api/app/todo-core/tasks",
      body: { title: `${label} ${suffix}` },
    });
    assert.equal(response.status, 201);
    return (response.body as { task: { id: string } }).task.id;
  };

  const firstTaskId = await createTask("Review UI task");
  const seeded = await ctx.request({
    method: "POST",
    path: `/api/app/todo-review/tasks/${firstTaskId}/reviews`,
    body: { summary: `UI 复盘总结 ${suffix}` },
  });
  assert.equal(seeded.status, 201);

  const secondTaskId = await createTask("Review UI cancel task");

  const openPage = ctx.openBrowserPage as unknown as (
    target?: string,
  ) => Promise<BrowserHandle>;
  const handle = await openPage("/");
  const page = handle.page;

  try {
    await page.waitForSelector(`[data-todo-item="${firstTaskId}"]`, {
      timeout: 8000,
    });
    await page.waitForSelector(
      `[data-todo-review-badge="${firstTaskId}"][data-todo-review-status="pending"]`,
      { timeout: 8000 },
    );

    // Toggling the core checkbox must open the review modal instead of
    // completing the task. The pre-seeded summary also proves the dialog is
    // prefilled from the server, so submitting needs no typing.
    await page.click(`[data-todo-toggle="${firstTaskId}"]`);
    await page.waitForSelector('[data-todo-review-dialog="true"]', {
      timeout: 8000,
    });

    const stateWhileDialog = await page.getAttribute(
      `[data-todo-item="${firstTaskId}"]`,
      "data-todo-state",
    );
    assert.equal(stateWhileDialog, "open");

    await page.click('[data-todo-review-submit="true"]');
    await waitForGone(page, '[data-todo-review-dialog="true"]');

    // Done tasks leave the default "open" filter, so switch to all to observe
    // the persisted state and the refreshed review badge.
    await page.click('[data-todo-filter="all"]');
    await page.waitForSelector(
      `[data-todo-item="${firstTaskId}"][data-todo-state="done"]`,
      { timeout: 8000 },
    );
    await page.waitForSelector(
      `[data-todo-review-badge="${firstTaskId}"][data-todo-review-status="consumed"]`,
      { timeout: 8000 },
    );

    const latest = await ctx.request({
      method: "GET",
      path: `/api/app/todo-review/tasks/${firstTaskId}/review`,
    });
    assert.equal(latest.status, 200);
    const review = (
      latest.body as {
        review: { status: string; summary: string } | null;
      }
    ).review;
    assert.ok(review);
    assert.equal(review.status, "consumed");
    assert.match(review.summary, new RegExp(suffix));

    // Cancelling the modal must abort the transition and surface the core
    // error banner so the task stays open.
    await page.click(`[data-todo-toggle="${secondTaskId}"]`);
    await page.waitForSelector('[data-todo-review-dialog="true"]', {
      timeout: 8000,
    });
    await page.click('[data-todo-review-cancel="true"]');
    await waitForGone(page, '[data-todo-review-dialog="true"]');
    await page.waitForSelector('[data-todo-error="true"]', {
      timeout: 8000,
    });

    const cancelledState = await page.getAttribute(
      `[data-todo-item="${secondTaskId}"]`,
      "data-todo-state",
    );
    assert.equal(cancelledState, "open");

    const pageErrors = handle.pageErrors ?? [];
    assert.equal(
      pageErrors.length,
      0,
      `client errors: ${pageErrors.map((item) => String(item)).join(" | ")}`,
    );
  } finally {
    if (typeof handle.close === "function") {
      await handle.close();
    }
  }
}

