function TagsDetail({ task }: ItemSlotProps) {
  const state = useTagState();
  const [draft, setDraft] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const tags = state.assignments[task.id] ?? [];
  const assignedIds = new Set(tags.map((tag) => tag.id));
  const available = state.tags.filter((tag) => !assignedIds.has(tag.id));

  const run = async (action: () => Promise<void>) => {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      await action();
    } catch (actionError) {
      setError(describe(actionError));
    } finally {
      setBusy(false);
    }
  };

  const handleCreate = async (event: FormEvent) => {
    event.preventDefault();
    const name = draft.trim();
    if (!name || busy) return;
    await run(async () => {
      const tag = await createTag(name);
      await attachTag(task.id, tag.id);
      setDraft("");
    });
  };

  return (
    <div data-todo-tags-detail={task.id} className="space-y-2">
      <div className="flex items-center justify-between">
        <h3 className="text-xs font-medium text-muted">标签</h3>
        <span className="text-[11px] text-muted tabular-nums">
          {tags.length} 个
        </span>
      </div>

      <div
        data-tag-detail-chips={task.id}
        className="flex flex-wrap items-center gap-1.5"
      >
        {tags.length === 0 ? (
          <span className="text-xs text-muted">暂无标签</span>
        ) : (
          tags.map((tag) => (
            <TagChip
              key={tag.id}
              tag={tag}
              onRemove={() =>
                void run(async () => {
                  await detachTag(task.id, tag.id);
                })
              }
            />
          ))
        )}
      </div>

      {available.length > 0 && (
        <div className="flex flex-wrap items-center gap-1.5">
          {available.map((tag) => (
            <button
              key={tag.id}
              type="button"
              data-tag-add={tag.id}
              disabled={busy}
              onClick={() =>
                void run(async () => {
                  await attachTag(task.id, tag.id);
                })
              }
              className="inline-flex max-w-[10rem] items-center gap-1 rounded-full border border-dashed border-line px-2 py-0.5 text-[11px] text-muted transition-colors hover:border-accent hover:text-accent disabled:opacity-50"
            >
              <Plus className="size-3 shrink-0" aria-hidden="true" />
              <span className="truncate">{tag.name}</span>
            </button>
          ))}
        </div>
      )}

      <form
        onSubmit={(event) => void handleCreate(event)}
        className="flex items-center gap-1.5"
      >
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="新建并添加标签"
          aria-label="新建并添加标签"
          data-tag-detail-create-input="true"
          className="min-h-9 w-full rounded-md border border-line bg-canvas px-2.5 py-1.5 text-xs text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
        />
        <button
          type="submit"
          disabled={busy || !draft.trim()}
          data-tag-detail-create-submit="true"
          aria-label="新建并添加标签"
          className="inline-flex size-9 shrink-0 items-center justify-center rounded-md bg-accent text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
        >
          <Plus className="size-4" aria-hidden="true" />
        </button>
      </form>

      {error && (
        <p role="alert" data-tag-detail-error="true" className="text-xs text-danger">
          {error}
        </p>
      )}
    </div>
  );
}

