import {
  useEffect,
  useMemo,
  useState,
  type ComponentType,
  type FormEvent,
} from "react";
import type { Context } from "cordis";
import { Check, Plus, Tag as TagIcon, Trash2, X } from "lucide-react";
import { useNavigate } from "@host/client-sdk";

interface TodoTag {
  readonly id: string;
  readonly name: string;
  readonly color: string;
  readonly createdAt: string;
}

interface TaskRef {
  readonly id: string;
  readonly title?: string;
  readonly state?: string;
}

interface ItemSlotProps {
  readonly task: TaskRef;
  readonly refresh?: () => Promise<void>;
}

interface TagState {
  tags: TodoTag[];
  assignments: Record<string, TodoTag[]>;
  error: string;
  loaded: boolean;
}

const TAG_API = "/api/app/todo-tags";
const FALLBACK_COLOR = "#64748b";
const PALETTE = [
  "#ef4444",
  "#f97316",
  "#f59e0b",
  "#10b981",
  "#06b6d4",
  "#3b82f6",
  "#8b5cf6",
  "#ec4899",
];

const tagState: TagState = {
  tags: [],
  assignments: {},
  error: "",
  loaded: false,
};

const listeners = new Set<() => void>();

function notify(): void {
  for (const listener of Array.from(listeners)) {
    listener();
  }
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function describe(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

async function requestJson<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, {
    ...init,
    headers: {
      "content-type": "application/json",
      ...(init?.headers ?? {}),
    },
  });
  const text = await response.text();
  const data = text ? (JSON.parse(text) as Record<string, unknown>) : {};
  if (!response.ok) {
    const detail =
      typeof data.error === "string" && data.error.length > 0
        ? data.error
        : `请求失败 (${response.status})`;
    throw new Error(detail);
  }
  return data as T;
}

let inflight: Promise<void> | null = null;

async function loadTagState(force = false): Promise<void> {
  if (tagState.loaded && !force) return;
  if (inflight) return inflight;

  inflight = (async () => {
    try {
      const [tagResult, assignmentResult] = await Promise.all([
        requestJson<{ tags: TodoTag[] }>(`${TAG_API}/tags`),
        requestJson<{ assignments: Record<string, TodoTag[]> }>(
          `${TAG_API}/assignments`,
        ),
      ]);
      tagState.tags = tagResult.tags ?? [];
      tagState.assignments = assignmentResult.assignments ?? {};
      tagState.error = "";
      tagState.loaded = true;
    } catch (error) {
      tagState.error = describe(error);
    } finally {
      inflight = null;
      notify();
    }
  })();

  return inflight;
}

function nextColor(): string {
  const color = PALETTE[tagState.tags.length % PALETTE.length];
  return typeof color === "string" ? color : FALLBACK_COLOR;
}

function replaceAssignments(taskId: string, tags: readonly TodoTag[]): void {
  tagState.assignments = {
    ...tagState.assignments,
    [taskId]: Array.from(tags),
  };
  notify();
}

async function createTag(name: string, color?: string): Promise<TodoTag> {
  const result = await requestJson<{
    tag: TodoTag;
    deduplicated?: boolean;
  }>(`${TAG_API}/tags`, {
    method: "POST",
    body: JSON.stringify({ name, color: color ?? nextColor() }),
  });
  // The server normalizes new names and may resolve a case-variant save to an
  // existing tag, so merge by id instead of blindly appending a duplicate.
  tagState.tags = [
    ...tagState.tags.filter((tag) => tag.id !== result.tag.id),
    result.tag,
  ].sort((left, right) => left.name.localeCompare(right.name));
  notify();
  return result.tag;
}

async function removeTag(tagId: string): Promise<void> {
  await requestJson(`${TAG_API}/tags/${encodeURIComponent(tagId)}`, {
    method: "DELETE",
  });
  tagState.tags = tagState.tags.filter((tag) => tag.id !== tagId);
  const next: Record<string, TodoTag[]> = {};
  for (const taskId of Object.keys(tagState.assignments)) {
    next[taskId] = (tagState.assignments[taskId] ?? []).filter(
      (tag) => tag.id !== tagId,
    );
  }
  tagState.assignments = next;
  notify();
}

async function setTaskTags(
  taskId: string,
  tagIds: readonly string[],
): Promise<void> {
  const result = await requestJson<{ tags: TodoTag[] }>(
    `${TAG_API}/tasks/${encodeURIComponent(taskId)}/tags`,
    { method: "PUT", body: JSON.stringify({ tagIds }) },
  );
  replaceAssignments(taskId, result.tags ?? []);
}

async function attachTag(taskId: string, tagId: string): Promise<void> {
  const result = await requestJson<{ tags: TodoTag[] }>(
    `${TAG_API}/tasks/${encodeURIComponent(taskId)}/tags`,
    { method: "POST", body: JSON.stringify({ tagId }) },
  );
  replaceAssignments(taskId, result.tags ?? []);
}

async function detachTag(taskId: string, tagId: string): Promise<void> {
  const result = await requestJson<{ tags: TodoTag[] }>(
    `${TAG_API}/tasks/${encodeURIComponent(taskId)}/tags/${encodeURIComponent(tagId)}`,
    { method: "DELETE" },
  );
  replaceAssignments(taskId, result.tags ?? []);
}

function useTagState(): TagState {
  const [, setVersion] = useState(0);

  useEffect(() => {
    const unsubscribe = subscribe(() => setVersion((value) => value + 1));
    void loadTagState();
    return unsubscribe;
  }, []);

  return tagState;
}

function TagChip({
  tag,
  onRemove,
}: {
  readonly tag: TodoTag;
  readonly onRemove?: () => void;
}) {
  return (
    <span
      data-tag-chip={tag.id}
      style={{
        borderColor: `${tag.color}55`,
        backgroundColor: `${tag.color}18`,
        color: tag.color,
      }}
      className="inline-flex max-w-[10rem] items-center gap-1 rounded-full border px-2 py-0.5 text-[11px] font-medium"
    >
      <span className="truncate">{tag.name}</span>
      {onRemove && (
        <button
          type="button"
          data-tag-remove={tag.id}
          aria-label={`移除标签：${tag.name}`}
          onClick={onRemove}
          className="inline-flex size-4 shrink-0 items-center justify-center rounded-full hover:bg-black/10"
        >
          <X className="size-3" aria-hidden="true" />
        </button>
      )}
    </span>
  );
}

function TagEditorDialog({
  taskId,
  taskTitle,
  initialTagIds,
  onClose,
}: {
  readonly taskId: string;
  readonly taskTitle: string;
  readonly initialTagIds: readonly string[];
  readonly onClose: () => void;
}) {
  const state = useTagState();
  const [selected, setSelected] = useState<string[]>(() =>
    Array.from(initialTagIds),
  );
  const [draft, setDraft] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const toggle = (tagId: string) => {
    setSelected((current) =>
      current.includes(tagId)
        ? current.filter((id) => id !== tagId)
        : [...current, tagId],
    );
  };

  const handleCreate = async (event: FormEvent) => {
    event.preventDefault();
    const name = draft.trim();
    if (!name || busy) return;
    setBusy(true);
    setError("");
    try {
      const tag = await createTag(name);
      setSelected((current) =>
        current.includes(tag.id) ? current : [...current, tag.id],
      );
      setDraft("");
    } catch (createError) {
      setError(describe(createError));
    } finally {
      setBusy(false);
    }
  };

  const handleSave = async () => {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      await setTaskTags(taskId, selected);
      onClose();
    } catch (saveError) {
      setError(describe(saveError));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center p-3 md:items-center">
      <button
        type="button"
        aria-label="关闭标签编辑"
        data-tag-editor-backdrop="true"
        onClick={onClose}
        className="absolute inset-0 h-full w-full cursor-default bg-black/35"
      />
      <div
        role="dialog"
        aria-modal="true"
        aria-label={`编辑标签：${taskTitle}`}
        data-tag-editor={taskId}
        className="relative flex w-full max-w-sm flex-col gap-3 rounded-xl border border-line bg-surface p-4 shadow-2xl"
      >
        <div className="flex items-start justify-between gap-2">
          <div className="min-w-0">
            <h3 className="truncate text-sm font-semibold text-ink">编辑标签</h3>
            <p className="truncate text-xs text-muted">{taskTitle}</p>
          </div>
          <button
            type="button"
            data-tag-editor-close="true"
            aria-label="关闭标签编辑"
            onClick={onClose}
            className="inline-flex size-8 shrink-0 items-center justify-center rounded-md text-muted transition-colors hover:bg-canvas hover:text-ink"
          >
            <X className="size-4" aria-hidden="true" />
          </button>
        </div>

        <div className="max-h-56 min-h-0 space-y-1.5 overflow-y-auto">
          {state.tags.length === 0 ? (
            <p className="rounded-md border border-dashed border-line px-3 py-4 text-center text-xs text-muted">
              还没有标签，在下方创建第一个标签
            </p>
          ) : (
            state.tags.map((tag) => {
              const isSelected = selected.includes(tag.id);
              return (
                <button
                  key={tag.id}
                  type="button"
                  data-tag-toggle={tag.id}
                  data-tag-selected={isSelected ? "true" : "false"}
                  disabled={busy}
                  onClick={() => toggle(tag.id)}
                  className={`flex w-full items-center justify-between gap-2 rounded-md border px-2.5 py-2 text-left text-sm transition-colors disabled:opacity-60 ${
                    isSelected
                      ? "border-accent bg-accent-soft text-ink"
                      : "border-line bg-canvas text-ink hover:bg-line/40"
                  }`}
                >
                  <span className="flex min-w-0 items-center gap-2">
                    <span
                      className="size-2.5 shrink-0 rounded-full"
                      style={{ backgroundColor: tag.color }}
                    />
                    <span className="truncate">{tag.name}</span>
                  </span>
                  <span
                    className={`flex size-4 shrink-0 items-center justify-center rounded border ${
                      isSelected
                        ? "border-accent bg-accent text-surface"
                        : "border-line"
                    }`}
                  >
                    {isSelected && <Check className="size-3" aria-hidden="true" />}
                  </span>
                </button>
              );
            })
          )}
        </div>

        <form
          onSubmit={(event) => void handleCreate(event)}
          className="flex items-center gap-1.5"
        >
          <input
            type="text"
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            placeholder="新建标签名称"
            aria-label="新建标签名称"
            data-tag-editor-create-input="true"
            className="min-h-9 w-full rounded-md border border-line bg-canvas px-2.5 py-1.5 text-xs text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
          />
          <button
            type="submit"
            disabled={busy || !draft.trim()}
            data-tag-editor-create-submit="true"
            aria-label="创建标签"
            className="inline-flex size-9 shrink-0 items-center justify-center rounded-md bg-accent text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
          >
            <Plus className="size-4" aria-hidden="true" />
          </button>
        </form>

        {error && (
          <p role="alert" data-tag-editor-error="true" className="text-xs text-danger">
            {error}
          </p>
        )}

        <div className="flex items-center justify-end gap-2">
          <button
            type="button"
            data-tag-editor-cancel="true"
            onClick={onClose}
            className="inline-flex min-h-9 items-center justify-center rounded-md border border-line bg-surface px-3 text-sm text-ink transition-colors hover:bg-canvas"
          >
            取消
          </button>
          <button
            type="button"
            disabled={busy}
            data-tag-editor-save="true"
            onClick={() => void handleSave()}
            className="inline-flex min-h-9 items-center justify-center rounded-md bg-accent px-3.5 text-sm font-medium text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
          >
            保存标签
          </button>
        </div>
      </div>
    </div>
  );
}

function TagsBadges({ task }: ItemSlotProps) {
  const state = useTagState();
  const [editing, setEditing] = useState(false);
  const tags = state.assignments[task.id] ?? [];

  return (
    <span
      data-todo-tags-badges={task.id}
      className="flex items-center gap-1.5"
    >
      {tags.map((tag) => (
        <TagChip key={tag.id} tag={tag} />
      ))}
      <button
        type="button"
        data-tag-edit={task.id}
        aria-label={`编辑标签：${task.title ?? task.id}`}
        onClick={() => setEditing(true)}
        className="inline-flex size-6 shrink-0 items-center justify-center rounded-full border border-line bg-surface text-muted transition-colors hover:border-accent hover:text-accent"
      >
        <TagIcon className="size-3.5" aria-hidden="true" />
      </button>
      {editing && (
        <TagEditorDialog
          taskId={task.id}
          taskTitle={task.title ?? task.id}
          initialTagIds={tags.map((tag) => tag.id)}
          onClose={() => setEditing(false)}
        />
      )}
    </span>
  );
}

function TagsDetail({ task }: ItemSlotProps) {
  const state = useTagState();
  const [draft, setDraft] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const tags = state.assignments[task.id] ?? [];
  const assignedIds = new Set(tags.map((tag) => tag.id));
  const available = state.tags.filter((tag) => !assignedIds.has(tag.id));

  const run = async (action: () => Promise<void>) => {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      await action();
    } catch (actionError) {
      setError(describe(actionError));
    } finally {
      setBusy(false);
    }
  };

  const handleCreate = async (event: FormEvent) => {
    event.preventDefault();
    const name = draft.trim();
    if (!name || busy) return;
    await run(async () => {
      const tag = await createTag(name);
      await attachTag(task.id, tag.id);
      setDraft("");
    });
  };

  return (
    <div data-todo-tags-detail={task.id} className="space-y-2">
      <div className="flex items-center justify-between">
        <h3 className="text-xs font-medium text-muted">标签</h3>
        <span className="text-[11px] text-muted tabular-nums">
          {tags.length} 个
        </span>
      </div>

      <div
        data-tag-detail-chips={task.id}
        className="flex flex-wrap items-center gap-1.5"
      >
        {tags.length === 0 ? (
          <span className="text-xs text-muted">暂无标签</span>
        ) : (
          tags.map((tag) => (
            <TagChip
              key={tag.id}
              tag={tag}
              onRemove={() =>
                void run(async () => {
                  await detachTag(task.id, tag.id);
                })
              }
            />
          ))
        )}
      </div>

      {available.length > 0 && (
        <div className="flex flex-wrap items-center gap-1.5">
          {available.map((tag) => (
            <button
              key={tag.id}
              type="button"
              data-tag-add={tag.id}
              disabled={busy}
              onClick={() =>
                void run(async () => {
                  await attachTag(task.id, tag.id);
                })
              }
              className="inline-flex max-w-[10rem] items-center gap-1 rounded-full border border-dashed border-line px-2 py-0.5 text-[11px] text-muted transition-colors hover:border-accent hover:text-accent disabled:opacity-50"
            >
              <Plus className="size-3 shrink-0" aria-hidden="true" />
              <span className="truncate">{tag.name}</span>
            </button>
          ))}
        </div>
      )}

      <form
        onSubmit={(event) => void handleCreate(event)}
        className="flex items-center gap-1.5"
      >
        <input
          type="text"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder="新建并添加标签"
          aria-label="新建并添加标签"
          data-tag-detail-create-input="true"
          className="min-h-9 w-full rounded-md border border-line bg-canvas px-2.5 py-1.5 text-xs text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
        />
        <button
          type="submit"
          disabled={busy || !draft.trim()}
          data-tag-detail-create-submit="true"
          aria-label="新建并添加标签"
          className="inline-flex size-9 shrink-0 items-center justify-center rounded-md bg-accent text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
        >
          <Plus className="size-4" aria-hidden="true" />
        </button>
      </form>

      {error && (
        <p role="alert" data-tag-detail-error="true" className="text-xs text-danger">
          {error}
        </p>
      )}
    </div>
  );
}

function TagsHeaderAction() {
  const state = useTagState();
  const navigate = useNavigate();

  return (
    <button
      type="button"
      data-todo-tags-entry="true"
      onClick={() => navigate("/tags")}
      className="inline-flex items-center gap-1.5 rounded-md border border-line bg-surface px-2.5 py-1.5 text-xs text-muted transition-colors hover:border-accent hover:text-accent"
    >
      <TagIcon className="size-3.5" aria-hidden="true" />
      <span>标签</span>
      <span data-todo-tags-count="true" className="text-[11px] tabular-nums">
        {state.tags.length}
      </span>
    </button>
  );
}

function TodoTagsPage() {
  const state = useTagState();
  const [draft, setDraft] = useState("");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");

  const usage = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const taskId of Object.keys(state.assignments)) {
      for (const tag of state.assignments[taskId] ?? []) {
        counts[tag.id] = (counts[tag.id] ?? 0) + 1;
      }
    }
    return counts;
  }, [state.tags, state.assignments]);

  const handleCreate = async (event: FormEvent) => {
    event.preventDefault();
    const name = draft.trim();
    if (!name || busy) return;
    setBusy(true);
    setError("");
    try {
      await createTag(name);
      setDraft("");
    } catch (createError) {
      setError(describe(createError));
    } finally {
      setBusy(false);
    }
  };

  const handleRemove = async (tagId: string) => {
    if (busy) return;
    setBusy(true);
    setError("");
    try {
      await removeTag(tagId);
    } catch (removeError) {
      setError(describe(removeError));
    } finally {
      setBusy(false);
    }
  };

  return (
    <div
      data-todo-tags-page="true"
      className="flex min-h-0 flex-1 flex-col bg-canvas text-ink"
    >
      <header className="border-b border-line px-6 pt-6 pb-4">
        <h1 className="text-[26px] font-semibold tracking-tight text-ink">
          标签
        </h1>
        <p className="mt-1 text-sm text-muted">
          维护任务标签库，在任务行徽标或任务详情中为任务打标签。
        </p>
      </header>

      <div className="min-h-0 flex-1 overflow-y-auto px-6 py-4">
        <form
          onSubmit={(event) => void handleCreate(event)}
          className="mb-2 flex items-center gap-2"
        >
          <input
            type="text"
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            placeholder="新建标签名称"
            aria-label="新建标签名称"
            data-todo-tags-create-input="true"
            className="min-h-10 w-full max-w-sm rounded-md border border-line bg-surface px-3 py-2 text-sm text-ink outline-none focus:border-accent focus:ring-1 focus:ring-accent"
          />
          <button
            type="submit"
            disabled={busy || !draft.trim()}
            data-todo-tags-create-submit="true"
            className="inline-flex min-h-10 shrink-0 items-center justify-center rounded-md bg-accent px-4 text-sm font-medium text-surface transition-colors hover:bg-accent/90 disabled:opacity-45"
          >
            创建标签
          </button>
        </form>

        <p
          data-todo-tags-policy="true"
          className="mb-4 text-xs text-muted"
        >
          新标签名称保存时自动转为小写，重名会复用已有标签；历史标签保持原有写法。
        </p>

        {error && (
          <p
            role="alert"
            data-todo-tags-error="true"
            className="mb-3 rounded-md border border-danger/25 bg-danger/5 px-3 py-2 text-sm text-danger"
          >
            {error}
          </p>
        )}

        {state.tags.length === 0 ? (
          <div
            data-todo-tags-empty="true"
            className="rounded-lg border border-dashed border-line bg-surface/60 px-4 py-8 text-center text-sm text-muted"
          >
            还没有标签，先创建第一个标签
          </div>
        ) : (
          <ul data-todo-tags-list="true" className="space-y-1.5">
            {state.tags.map((tag) => (
              <li
                key={tag.id}
