                  <button
                    type="button"
                    data-todo-tag-delete={tag.id}
                    disabled={busy}
                    aria-label={`删除标签：${tag.name}`}
                    onClick={() => void handleRemove(tag.id)}
                    className="inline-flex size-8 items-center justify-center rounded-md text-danger transition-colors hover:bg-danger/10 disabled:opacity-45"
                  >
                    <Trash2 className="size-4" aria-hidden="true" />
                  </button>
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

type AnyFunction = (arg: unknown, second?: unknown, third?: unknown) => unknown;

function pick(source: unknown, key: string): unknown {
  try {
    if (!source || typeof source !== "object") return undefined;
    return (source as Record<string, unknown>)[key];
  } catch {
    return undefined;
  }
}

function registerSlot<P>(
  ctx: Context,
  name: string,
  component: ComponentType<P>,
  order: number,
): void {
  const holders: unknown[] = [
    pick(ctx, "slot"),
    pick(ctx, "slots"),
    pick(pick(ctx, "router"), "slot"),
    pick(pick(ctx, "router"), "slots"),
    pick(pick(ctx, "ui"), "slot"),
    pick(pick(ctx, "ui"), "slots"),
    pick(pick(ctx, "client"), "slot"),
    pick(pick(ctx, "client"), "slots"),
  ];

  for (const holder of holders) {
    if (!holder) continue;

    const registrars: unknown[] = [];
    if (typeof holder === "function") {
      registrars.push(holder);
    } else if (typeof holder === "object") {
      const api = holder as { register?: unknown; add?: unknown };
      if (typeof api.register === "function") registrars.push(api.register);
      if (typeof api.add === "function") registrars.push(api.add);
    }

    for (const registrar of registrars) {
      const register = registrar as AnyFunction;
      const objectForm = () => register.call(holder, { name, order, component });
      const argsForm = () => register.call(holder, name, component, { order });
      const attempts =
        register.length >= 2 ? [argsForm, objectForm] : [objectForm, argsForm];

      for (const attempt of attempts) {
        try {
          attempt();
          return;
        } catch {
          // try the next registration shape
        }
      }
    }
  }
}

export default function apply(ctx: Context): void {
  registerSlot(ctx, "todo.item.badges", TagsBadges, 20);
  registerSlot(ctx, "todo.item.detail", TagsDetail, 30);
  registerSlot(ctx, "todo.header.actions", TagsHeaderAction, 20);

  ctx.router.registerPage({
    path: "/tags",
    navLabel: "标签",
    order: 20,
    component: TodoTagsPage,
  });
}

